window.GRAIN_INDEX = {"roles":[{"slug":"accountants-auditors","soc":"13-2011.00","cluster":"knowledge","label":"Accountants & Auditors","onetTitle":"Accountants and Auditors","basis":null,"counts":{"u":0,"a":15,"x":5,"n":4},"tasks":[{"id":"21505","text":"Prepare detailed reports on audit findings.","b":"a","r":"AI drafts the findings report from the workpapers; the auditor signs the opinion.","bl":false},{"id":"21506","text":"Report to management about asset utilization and audit results, and recommend changes in operations and financial activities.","b":"a","r":"AI prepares the summary and options; recommending change to management is persuasion.","bl":false},{"id":"21507","text":"Collect and analyze data to detect deficient controls, duplicated effort, extravagance, fraud, or non-compliance with laws, regulations, and management policies.","b":"a","r":"AI scans the full dataset for anomalies; judging which anomalies matter is the audit.","bl":false},{"id":"21508","text":"Inspect account books and accounting systems for efficiency, effectiveness, and use of accepted accounting procedures to record transactions.","b":"a","r":"AI tests procedures continuously across all transactions; evaluating the system design stays human.","bl":false},{"id":"21509","text":"Supervise auditing of establishments, and determine scope of investigation required.","b":"a","r":"AI drafts the scope from risk data; the judgement about where to look stays with the auditor.","bl":false},{"id":"21510","text":"Confer with company officials about financial and regulatory matters.","b":"a","r":"AI prepares the briefing; conferring with officials is trust and negotiation.","bl":false},{"id":"21511","text":"Examine and evaluate financial and information systems, recommending controls to ensure system reliability and data integrity.","b":"a","r":"AI maps the systems and flags control gaps; recommending controls needs organisational context.","bl":false},{"id":"21512","text":"Inspect cash on hand, notes receivable and payable, negotiable securities, and canceled checks to confirm records are accurate.","b":"x","r":"Confirming records against source documents is matching at volume. Machines match.","bl":false},{"id":"21513","text":"Examine records and interview workers to ensure recording of transactions and compliance with laws and regulations.","b":"a","r":"AI analyses the transaction records; interviewing workers about them stays human.","bl":false},{"id":"21514","text":"Prepare, examine, or analyze accounting records, financial statements, or other financial reports to assess accuracy, completeness, and conformance to reporting and procedural standards.","b":"a","r":"AI checks accuracy and conformance continuously; assessing what the numbers mean stays human.","bl":true},{"id":"21515","text":"Prepare adjusting journal entries.","b":"x","r":"Standard adjusting entries follow rules. Post automatically, review by exception.","bl":false},{"id":"21516","text":"Review accounts for discrepancies and reconcile differences.","b":"x","r":"Reconciliation is definitionally automatable. It should have been years ago.","bl":false},{"id":"21517","text":"Establish tables of accounts and assign entries to proper accounts.","b":"x","r":"Assigning entries to accounts against a chart of accounts is classification. AI classifies.","bl":false},{"id":"21518","text":"Examine inventory to verify journal and ledger entries.","b":"a","r":"AI flags the mismatches; verifying physical inventory sometimes needs a person with a clipboard.","bl":true},{"id":"21519","text":"Analyze business operations, trends, costs, revenues, financial commitments, and obligations to project future revenues and expenses or to provide advice.","b":"a","r":"AI builds the projections; advising on the commitments behind them stays human.","bl":false},{"id":"21520","text":"Report to management regarding the finances of establishment.","b":"a","r":"AI drafts the financial report; reporting to management carries accountability.","bl":false},{"id":"21521","text":"Develop, implement, modify, and document recordkeeping and accounting systems, making use of current computer technology.","b":"a","r":"AI configures and documents the systems; designing the control environment stays human.","bl":false},{"id":"21522","text":"Evaluate taxpayer finances to determine tax liability, using knowledge of interest and discount rates, annuities, valuation of stocks and bonds, and amortization valuation of depletable assets.","b":"a","r":"AI computes the liability from the rules; advising on the position stays human.","bl":false},{"id":"21523","text":"Examine whether the organization's objectives are reflected in its management activities, and whether employees understand the objectives.","b":"a","r":"AI gathers the evidence; judging whether objectives are understood needs conversation.","bl":false},{"id":"21524","text":"Audit payroll and personnel records to determine unemployment insurance premiums, workers' compensation coverage, liabilities, and compliance with tax laws.","b":"x","r":"Payroll compliance testing against tax rules is rule checking at volume.","bl":false}],"new":[{"t":"Audit the AI's audit: sample its exception calls","r":"When AI checks everything, the skill is checking the checker."},{"t":"Verify AI-drafted opinions and reports before signature","r":"The signature is personal liability. The draft is not."},{"t":"Run continuous auditing instead of annual sampling","r":"The technology allows it; clients will expect it; someone must interpret it."},{"t":"Design the controls for automated bookkeeping itself","r":"Who checks the rules engine? The auditor's new frontier."}],"moves":{"u":"Judgement, interviews and the signature stay. Audit opinion is personal accountability.","a":"Let AI test everything and draft everything. The auditor reviews, questions and signs.","x":"Automate reconciliation, matching and compliance testing. This is overdue, not radical.","n":"Build the continuous audit practice. Sampling is over; total coverage with human judgement is the new standard."},"take":"Bookkeeping collapses into software and audit transforms from sampling to total coverage. The profession's centre of gravity moves to judgement, advisory and the one thing no model can hold: the signature."},{"slug":"comp-benefits-analysts","soc":"13-1141.00","cluster":"people","label":"Compensation & Benefits Analysts","onetTitle":"Compensation, Benefits, and Job Analysis Specialists","basis":null,"counts":{"u":0,"a":9,"x":5,"n":4},"tasks":[{"id":"3359","text":"Administer employee insurance, pension, and savings plans, working with insurance brokers and plan carriers.","b":"x","r":"Administering plans with brokers and carriers is rule driven correspondence. Automate the routine.","bl":true},{"id":"3352","text":"Ensure company compliance with federal and state laws, including reporting requirements.","b":"x","r":"Compliance checking and statutory reporting against fixed rules. Software files, humans sample.","bl":false},{"id":"3363","text":"Research employee benefit and health and safety practices, and recommend changes or modifications to existing policies.","b":"a","r":"AI scans practice across the market continuously; recommending change for this workforce stays human.","bl":false},{"id":"3353","text":"Advise managers and employees on state and federal employment regulations, collective agreements, benefit and compensation policies, personnel procedures, and classification programs.","b":"a","r":"AI drafts the regulation summary; advising a manager on a live case keeps a person in it.","bl":false},{"id":"3369","text":"Plan and develop curricula and materials for training programs and conduct training.","b":"a","r":"AI assembles curricula and drafts materials; the analyst shapes what managers actually learn.","bl":false},{"id":"3357","text":"Assist in preparing and maintaining personnel records and handbooks.","b":"x","r":"Maintaining records and handbooks is documentation work. Systems keep them current.","bl":false},{"id":"23985","text":"Develop and administer compensation programs, such as merit or incentive pay.","b":"a","r":"AI models merit and incentive structures against data; designing the programme is judgement.","bl":false},{"id":"3351","text":"Evaluate job positions, determining classification, exempt or non-exempt status, and salary.","b":"a","r":"AI benchmarks the role and suggests a grade; classification disputes need a human ruling.","bl":true},{"id":"3356","text":"Prepare occupational classifications, job descriptions, and salary scales.","b":"x","r":"Drafting standard descriptions and scales from a library is production work. AI drafts, people approve.","bl":false},{"id":"3371","text":"Consult with, or serve as, technical liaison between business, industry, government, and union officials.","b":"a","r":"AI prepares the briefing packs; the liaison between business, government and unions is relationship work.","bl":false},{"id":"3362","text":"Perform multifactor data and cost analyses that may be used in areas such as support of collective bargaining agreements.","b":"x","r":"Multifactor cost analysis on defined datasets is computation. Ask the question, get the table.","bl":false},{"id":"3361","text":"Develop, implement, administer, and evaluate personnel and labor relations programs, including performance appraisal, affirmative action, and employment equity programs.","b":"a","r":"AI drafts and evaluates programme options; implementing them fairly stays human.","bl":false},{"id":"3355","text":"Provide advice on the resolution of classification and salary complaints.","b":"a","r":"AI retrieves precedent and policy; advising on a real person's pay complaint keeps judgement central.","bl":false},{"id":"3360","text":"Negotiate collective agreements on behalf of employers or workers, and mediate labor disputes and grievances.","b":"a","r":"AI models positions and drafts language; negotiating the agreement stays across the table.","bl":false}],"new":[{"t":"Audit AI-generated job evaluations for consistency","r":"The same job must get the same grade every time, and someone must check."},{"t":"Validate AI market benchmarking before pay decisions","r":"A bad benchmark quietly misprices hundreds of salaries."},{"t":"Run live pay equity analysis on every cycle","r":"Continuous equity checking becomes possible, and expected."},{"t":"Maintain the rules engine behind automated administration","r":"The automation is only as good as its rules. Owning them is a job."}],"moves":{"u":"Little here is untouchable. The moat is judgement about fairness, not production of documents.","a":"Move from producer to reviewer: AI drafts the analysis, the analyst checks it and defends it.","x":"Automate filings, records and standard documents. The spreadsheet era of this role is ending.","n":"Become the person who can prove pay is fair. That proof is new work, and it is valuable."},"take":"The analytical core of this role (benchmarking, modelling, documentation) is exactly what AI does fastest. The role tilts toward judgement: resolving the disputes, defending the grades, proving the fairness."},{"slug":"compensation-benefits-managers","soc":"11-3111.00","cluster":"people","label":"Compensation & Benefits Managers","onetTitle":"Compensation and Benefits Managers","basis":null,"counts":{"u":1,"a":11,"x":2,"n":4},"tasks":[{"id":"3267","text":"Direct preparation and distribution of written and verbal information to inform employees of benefits, compensation, and personnel policies.","b":"a","r":"AI drafts and personalises the communications; the manager approves what goes out under their name.","bl":false},{"id":"3272","text":"Design, evaluate, and modify benefits policies to ensure that programs are current, competitive, and in compliance with legal requirements.","b":"a","r":"AI models options against market data and law; designing the policy is judgement about this workforce.","bl":false},{"id":"3276","text":"Fulfill all reporting requirements of all relevant government rules and regulations, including the Employee Retirement Income Security Act (ERISA).","b":"x","r":"Regulatory reporting is rules, forms and deadlines. Software files it; a person reviews the exceptions.","bl":false},{"id":"3273","text":"Analyze compensation policies, government regulations, and prevailing wage rates to develop competitive compensation plan.","b":"a","r":"AI pulls wage surveys and builds the comparison; deciding where to position pay is strategy.","bl":false},{"id":"3271","text":"Identify and implement benefits to increase the quality of life for employees by working with brokers and researching benefits issues.","b":"a","r":"AI researches and compares broker offerings; choosing benefits for these people stays human.","bl":false},{"id":"3285","text":"Manage the design and development of tools to assist employees in benefits selection, and to guide managers through compensation decisions.","b":"a","r":"AI drafts the decision tools and guides; the manager owns what managers are taught to do.","bl":false},{"id":"3268","text":"Administer, direct, and review employee benefit programs, including the integration of benefit programs following mergers and acquisitions.","b":"a","r":"Administration moves to systems; integration after a merger needs human judgement throughout.","bl":true},{"id":"3275","text":"Mediate between benefits providers and employees, such as by assisting in handling employees' benefits-related questions or taking suggestions.","b":"x","r":"Routing benefits questions between providers and employees is a workflow with a knowledge base.","bl":false},{"id":"3270","text":"Plan, direct, supervise, and coordinate work activities of subordinates and staff relating to employment, compensation, labor relations, and employee relations.","b":"u","r":"Directing the team's work is leadership. No delegation.","bl":false},{"id":"3283","text":"Prepare detailed job descriptions and classification systems and define job levels and families, in partnership with other managers.","b":"a","r":"AI drafts job descriptions and structures from market data; job architecture stays a human design call.","bl":false},{"id":"3279","text":"Develop methods to improve employment policies, processes, and practices, and recommend changes to management.","b":"a","r":"AI analyses the policy landscape and drafts improvements; recommending change is judgement.","bl":false},{"id":"3274","text":"Formulate policies, procedures and programs for recruitment, testing, placement, classification, orientation, benefits and compensation, and labor and industrial relations.","b":"a","r":"AI drafts the programme documents; formulating policy for this organisation stays human.","bl":false},{"id":"3290","text":"Study legislation, arbitration decisions, and collective bargaining contracts to assess industry trends.","b":"a","r":"AI tracks legislation and case outcomes continuously; assessing the impact here is the craft.","bl":false},{"id":"3269","text":"Plan and conduct new-employee orientations to foster positive attitude toward organizational objectives.","b":"a","r":"AI personalises orientation content; the manager sets the tone the new starters remember.","bl":true}],"new":[{"t":"Audit pay algorithms for equity drift","r":"Automated pay recommendations can bake in bias silently. Someone must watch the watcher."},{"t":"Validate AI-drafted benefits communications","r":"A wrong sentence about pensions or cover becomes a legal problem."},{"t":"Model reward scenarios before board decisions","r":"Live modelling in the meeting changes what questions get asked."},{"t":"Own the data quality feeding pay benchmarking","r":"Benchmarks built on bad data misprice every role."}],"moves":{"u":"The leadership of the function stays put. Everything else on this list is up for redesign.","a":"Let AI draft, model and compare. The manager's hours move to design decisions and board level advice.","x":"Automate filings, routine queries and documentation. Compliance reporting should cost almost nothing.","n":"Get in front of pay equity auditing. Regulators are already asking how automated pay decisions are checked."},"take":"Reward is a data rich discipline, so AI hits it early and hard: analysis, drafting and reporting all accelerate. What remains is the judgement about fairness and competitiveness, which is precisely the part employees care about most."},{"slug":"customer-service-reps","soc":"43-4051.00","cluster":"knowledge","label":"Customer Service Representatives","onetTitle":"Customer Service Representatives","basis":null,"counts":{"u":0,"a":8,"x":5,"n":4},"tasks":[{"id":"18565","text":"Confer with customers by telephone or in person to provide information about products or services, take or enter orders, cancel accounts, or obtain details of complaints.","b":"a","r":"AI resolves the standard enquiries instantly; the upset, complex or unusual cases escalate to a person.","bl":false},{"id":"2578","text":"Keep records of customer interactions or transactions, recording details of inquiries, complaints, or comments, as well as actions taken.","b":"x","r":"Interaction logging writes itself from the transcript.","bl":false},{"id":"2580","text":"Check to ensure that appropriate changes were made to resolve customers' problems.","b":"a","r":"AI checks resolution against the record; following up with the customer stays human.","bl":false},{"id":"2581","text":"Contact customers to respond to inquiries or to notify them of claim investigation results or any planned adjustments.","b":"x","r":"Outbound notifications of claim results are templated and triggered. Automate kindly.","bl":false},{"id":"2583","text":"Determine charges for services requested, collect deposits or payments, or arrange for billing.","b":"x","r":"Calculating charges and arranging billing against a price list is rules based.","bl":false},{"id":"2584","text":"Complete contract forms, prepare change of address records, or issue service discontinuance orders, using computers.","b":"x","r":"Contract forms and address changes are form filling. Software fills forms.","bl":false},{"id":"2582","text":"Refer unresolved customer grievances to designated departments for further investigation.","b":"a","r":"AI routes with full context attached; the grievance itself lands with a person who can fix it.","bl":false},{"id":"2579","text":"Resolve customers' service or billing complaints by performing activities such as exchanging merchandise, refunding money, or adjusting bills.","b":"a","r":"AI proposes the remedy within policy; the judgement call on a furious customer stays human.","bl":true},{"id":"2587","text":"Review insurance policy terms to determine whether a particular loss is covered by insurance.","b":"a","r":"AI checks the loss against policy terms; edge cases and denials need a human explanation.","bl":true},{"id":"2586","text":"Solicit sales of new or additional services or products.","b":"a","r":"AI drafts the offer from propensity data; the cross-sell conversation needs human timing.","bl":false},{"id":"2589","text":"Compare disputed merchandise with original requisitions and information from invoices and prepare invoices for returned goods.","b":"x","r":"Comparing disputed items against invoices is document matching.","bl":false},{"id":"2585","text":"Obtain and examine all relevant information to assess validity of complaints and to determine possible causes, such as extreme weather conditions that could increase utility bills.","b":"a","r":"AI assembles the case file; judging validity when the story does not fit the rules stays human.","bl":false},{"id":"2591","text":"Recommend improvements in products, packaging, shipping, service, or billing methods and procedures to prevent future problems.","b":"a","r":"AI clusters complaints into improvement themes; recommending change to the business stays human.","bl":false}],"new":[{"t":"Handle the escalations the AI cannot close","r":"What remains is harder than what was automated. Training must follow."},{"t":"Quality-check AI conversations for tone and accuracy","r":"Sample daily. The bot speaks for the brand in a thousand conversations at once."},{"t":"Feed the failure cases back into the knowledge base","r":"Every unresolved conversation is training data. Someone curates it."},{"t":"Own the handoff moment between bot and human","r":"The customer judges the company at exactly that seam."}],"moves":{"u":"Empathy under fire stays human. The role becomes the escalation layer, and it needs better training, not less.","a":"Let AI take first contact and routine resolution. People take the problems worth having.","x":"Automate logging, notifications and form work. None of it was why anyone took this job.","n":"Build the bot supervision craft: quality checks, knowledge curation, handoff design."},"take":"First-line volume moves to AI fast; what is left for people is the difficult residue: complaints, edge cases and churn saves. Fewer seats, harder conversations, and a new premium on the humans who can handle them."},{"slug":"data-scientists","soc":"15-2051.00","cluster":"knowledge","label":"Data Scientists / People Analysts","onetTitle":"Data Scientists","basis":null,"counts":{"u":1,"a":11,"x":2,"n":4},"tasks":[{"id":"21823","text":"Analyze, manipulate, or process large sets of data using statistical software.","b":"a","r":"AI writes the statistical code from a plain brief; the scientist designs the analysis and checks it.","bl":false},{"id":"21824","text":"Apply feature selection algorithms to models predicting outcomes of interest, such as sales, attrition, and healthcare use.","b":"a","r":"AI runs the feature selection sweeps; knowing which features are fair to use is judgement.","bl":false},{"id":"21825","text":"Apply sampling techniques to determine groups to be surveyed or use complete enumeration methods.","b":"a","r":"AI computes the sampling design; deciding who to study and why stays human.","bl":false},{"id":"21826","text":"Clean and manipulate raw data using statistical software.","b":"x","r":"Data cleaning scripts write and run themselves from a description of the mess.","bl":false},{"id":"21827","text":"Compare models using statistical performance metrics, such as loss functions or proportion of explained variance.","b":"x","r":"Model comparison on defined metrics is a sweep the machine runs overnight.","bl":false},{"id":"21828","text":"Create graphs, charts, or other visualizations to convey the results of data analysis using specialized software.","b":"a","r":"AI drafts the visualisations; choosing the honest chart for the audience stays human.","bl":true},{"id":"21829","text":"Deliver oral or written presentations of the results of mathematical modeling and data analysis to management or other end users.","b":"a","r":"AI drafts the deck; standing behind the findings in front of sceptics is the person.","bl":false},{"id":"21830","text":"Design surveys, opinion polls, or other instruments to collect data.","b":"a","r":"AI drafts survey instruments from best practice; wording that works on real people needs review.","bl":false},{"id":"21831","text":"Identify business problems or management objectives that can be addressed through data analysis.","b":"u","r":"Framing the business problem worth solving is conversation, context and politics.","bl":false},{"id":"21832","text":"Identify relationships and trends or any factors that could affect the results of research.","b":"a","r":"AI surfaces the patterns; deciding whether they are real, spurious or actionable is the craft.","bl":false},{"id":"21833","text":"Identify solutions to business problems, such as budgeting, staffing, and marketing decisions, using the results of data analysis.","b":"a","r":"AI drafts the recommendation with evidence; the scientist owns what gets acted on.","bl":true},{"id":"21834","text":"Propose solutions in engineering, the sciences, and other fields using mathematical theories and techniques.","b":"a","r":"AI applies the standard techniques fast; knowing when the standard technique is wrong is expertise.","bl":false},{"id":"21835","text":"Read scientific articles, conference papers, or other sources of research to identify emerging analytic trends and technologies.","b":"a","r":"AI tracks and summarises the literature continuously; judgement about what matters stays human.","bl":false},{"id":"21836","text":"Recommend data-driven solutions to key stakeholders.","b":"a","r":"AI prepares the stakeholder briefing; persuading a room of executives stays human.","bl":false}],"new":[{"t":"Audit models for bias and drift on a schedule","r":"Models decay and discriminate quietly. Scheduled auditing becomes standard practice."},{"t":"Verify AI-written analysis code line by line where it matters","r":"Fluent code with a subtle error produces confident wrong answers at scale."},{"t":"Translate between the AI's output and the board's question","r":"Someone must stand between the model and the decision, accountable for both."},{"t":"Curate the data the models learn from","r":"Garbage in now fails faster and louder. Data stewardship becomes core."}],"moves":{"u":"Problem framing is the durable skill. Everything downstream of a well framed question accelerates.","a":"Let AI write the first pass of code, charts and decks. Review rigorously; ship faster.","x":"Automate cleaning and model sweeps. The boring 60 percent of the job goes first.","n":"Become the accountable checker: bias audits, code review, translation to decisions."},"take":"The irony of the moment: the people who built the automation get automated early. Cleaning, coding and comparing compress into prompts. What survives is framing, judgement and accountability for what the model says."},{"slug":"executive-assistants","soc":"43-6011.00","cluster":"knowledge","label":"Executive Assistants","onetTitle":"Executive Secretaries and Executive Administrative Assistants","basis":null,"counts":{"u":1,"a":7,"x":7,"n":4},"tasks":[{"id":"2770","text":"Manage and maintain executives' schedules.","b":"x","r":"Diary management against preferences and constraints is a solver's work. The AI books around the rules.","bl":true},{"id":"2779","text":"Make travel arrangements for executives.","b":"x","r":"Travel booking is rules, preferences and inventory. End to end automatable with approval steps.","bl":false},{"id":"2771","text":"Prepare invoices, reports, memos, letters, financial statements, and other documents, using word processing, spreadsheet, database, or presentation software.","b":"a","r":"AI drafts the documents instantly; the assistant shapes tone and catches what matters.","bl":false},{"id":"18576","text":"Coordinate and direct office services, such as records, departmental finances, budget preparation, personnel issues, and housekeeping, to aid executives.","b":"a","r":"AI tracks budgets and records; coordinating office services still needs a person who knows the building.","bl":false},{"id":"18573","text":"Answer phone calls and direct calls to appropriate parties or take messages.","b":"x","r":"Call routing and message taking is a solved problem with a well configured assistant.","bl":false},{"id":"2776","text":"Prepare responses to correspondence containing routine inquiries.","b":"x","r":"Routine correspondence replies are templated and grounded. Review queue, not drafting.","bl":false},{"id":"2773","text":"Open, sort, and distribute incoming correspondence, including faxes and email.","b":"x","r":"Sorting and distributing incoming post and email is triage automation.","bl":false},{"id":"2775","text":"Greet visitors and determine whether they should be given access to specific individuals.","b":"u","r":"Greeting visitors and judging who gets access is security, courtesy and instinct at the door.","bl":false},{"id":"18575","text":"Prepare agendas and make arrangements, such as coordinating catering for luncheons, for committee, board, and other meetings.","b":"a","r":"AI drafts agendas and handles logistics; reading the politics of the meeting stays human.","bl":false},{"id":"2780","text":"Conduct research, compile data, and prepare papers for consideration and presentation by executives, committees, and boards of directors.","b":"a","r":"AI compiles the research and drafts the papers; deciding what the executive sees is judgement.","bl":false},{"id":"18574","text":"Perform general office duties, such as ordering supplies, maintaining records management database systems, and performing basic bookkeeping work.","b":"a","r":"AI handles records and bookkeeping flows; the odd problem that falls between systems lands on the person.","bl":false},{"id":"2774","text":"File and retrieve corporate documents, records, and reports.","b":"x","r":"Filing and retrieval is search. Automate it completely.","bl":false},{"id":"2772","text":"Read and analyze incoming memos, submissions, and reports to determine their significance and plan their distribution.","b":"a","r":"AI summarises and ranks incoming documents; judging significance for this executive stays human.","bl":true},{"id":"18577","text":"Provide clerical support to other departments.","b":"x","r":"Routine clerical support requests route and fulfil automatically.","bl":false},{"id":"2782","text":"Attend meetings to record minutes.","b":"a","r":"AI drafts minutes from the transcript; the assistant confirms what was actually decided.","bl":false}],"new":[{"t":"Run the executive's AI gatekeeping rules","r":"Who and what gets through is now a configured policy, and someone tunes it."},{"t":"Verify AI-drafted briefings before the executive reads them","r":"A wrong fact in a board pre read is a career event."},{"t":"Manage the executive's AI assistant itself","r":"Prompting, checking and correcting the tool is the new core skill."},{"t":"Guard the calendar against AI-optimised overload","r":"The tool will fill every gap. Protecting thinking time is human advocacy."}],"moves":{"u":"The door, the judgement and the discretion stay. The role gets smaller and more senior at once.","a":"Move from drafter to editor in chief. Everything gets a human pass, but nothing starts blank.","x":"Automate scheduling, travel, filing and triage. These are solved problems now.","n":"Become the executive's AI operator: the person who makes the tools actually deliver."},"take":"The administrative core of this role (scheduling, travel, filing, routine replies) is precisely what AI already does well. What remains is judgement, access and trust, which makes the surviving role smaller, senior and harder to hire for."},{"slug":"financial-analysts","soc":"13-2051.00","cluster":"knowledge","label":"Financial & Investment Analysts","onetTitle":"Financial and Investment Analysts","basis":null,"counts":{"u":1,"a":12,"x":1,"n":4},"tasks":[{"id":"21579","text":"Advise clients on aspects of capitalization, such as amounts, sources, or timing.","b":"a","r":"AI models the capitalisation options instantly; advising on timing and sources is judgement.","bl":false},{"id":"21580","text":"Analyze financial or operational performance of companies facing financial difficulties to identify or recommend remedies.","b":"a","r":"AI drafts the turnaround analysis from the financials; recommending remedies needs sector context.","bl":false},{"id":"21581","text":"Assess companies as investments for clients by examining company facilities.","b":"a","r":"AI screens the company exhaustively; the site visit and the smell test stay human.","bl":false},{"id":"21582","text":"Collaborate on projects with other professionals, such as lawyers, accountants, or public relations experts.","b":"a","r":"AI prepares the shared analysis; coordinating lawyers and accountants is relationship work.","bl":false},{"id":"21583","text":"Collaborate with investment bankers to attract new corporate clients.","b":"a","r":"AI drafts the pitch materials; winning the client is persuasion.","bl":false},{"id":"21584","text":"Conduct financial analyses related to investments in green construction or green retrofitting projects.","b":"a","r":"AI models the green project financials; assessing novel risk stays human.","bl":false},{"id":"21585","text":"Confer with clients to restructure debt, refinance debt, or raise new debt.","b":"a","r":"AI drafts restructuring options; conferring with clients under stress is trust work.","bl":false},{"id":"21586","text":"Create client presentations of plan details.","b":"a","r":"AI builds the deck from the model; the analyst owns the story it tells.","bl":false},{"id":"21587","text":"Determine the prices at which securities should be syndicated and offered to the public.","b":"a","r":"AI prices comparables instantly; the syndication call carries market judgement.","bl":true},{"id":"21588","text":"Develop and maintain client relationships.","b":"u","r":"Client relationships are dinners, trust and being there when it matters.","bl":false},{"id":"21589","text":"Draw charts and graphs, using computer spreadsheets, to illustrate technical reports.","b":"x","r":"Charts from data are generated, not drawn. This task is already a macro.","bl":false},{"id":"21590","text":"Employ financial models to develop solutions to financial problems or to assess the financial or capital impact of transactions.","b":"a","r":"AI builds and runs the models; choosing the assumptions is where the value lives.","bl":false},{"id":"21591","text":"Evaluate and compare the relative quality of various securities in a given industry.","b":"a","r":"AI ranks securities on every metric; the relative quality call is the analyst's edge.","bl":true},{"id":"21592","text":"Evaluate capital needs of clients and assess market conditions to inform structuring of financial packages.","b":"a","r":"AI assesses market conditions continuously; structuring the package is craft.","bl":false}],"new":[{"t":"Verify AI-built models before trading on them","r":"A broken formula in a generated model loses real money quietly."},{"t":"Interrogate AI research summaries against primary sources","r":"The confident summary that missed the footnote is the new career risk."},{"t":"Run AI scenario analysis live in client meetings","r":"The meeting changes when any question gets modelled on the spot."},{"t":"Document the basis for every AI-assisted recommendation","r":"Regulators will ask how the advice was produced. Be ready."}],"moves":{"u":"Relationships and trust stay. Capital still moves on confidence in a person.","a":"Let AI do the modelling and drafting. Compete on assumptions, judgement and speed.","x":"Chart production and data pulls are over as human tasks. Good riddance.","n":"Own verification. The analyst who can prove the model is right wins the desk."},"take":"Analysis production (the junior analyst's entire job) compresses toward zero cost. What remains is assumption setting, client trust and verified judgement. The apprenticeship model of this profession needs a redesign, urgently."},{"slug":"graphic-designers","soc":"27-1024.00","cluster":"knowledge","label":"Graphic Designers","onetTitle":"Graphic Designers","basis":null,"counts":{"u":0,"a":11,"x":6,"n":4},"tasks":[{"id":"307","text":"Key information into computer equipment to create layouts for client or supervisor.","b":"x","r":"Keying in layouts is production work. The tool now generates the layout from the brief.","bl":false},{"id":"304","text":"Review final layouts and suggest improvements, as needed.","b":"a","r":"Reviewing and refining generated layouts is the job now. Taste is the skill.","bl":false},{"id":"300","text":"Determine size and arrangement of illustrative material and copy, and select style and size of type.","b":"a","r":"AI proposes arrangements and type pairings; the designer's eye makes the final call.","bl":true},{"id":"306","text":"Develop graphics and layouts for product illustrations, company logos, and Web sites.","b":"a","r":"AI generates the options at volume; the designer directs, selects and refines.","bl":false},{"id":"299","text":"Create designs, concepts, and sample layouts, based on knowledge of layout principles and esthetic design concepts.","b":"a","r":"AI drafts concepts from the brief; the concept that wins still comes from human taste.","bl":true},{"id":"301","text":"Use computer software to generate new images.","b":"x","r":"Using software to generate images is exactly what image models do on command.","bl":false},{"id":"23970","text":"Prepare digital files for printing.","b":"x","r":"Preparing print ready files is preflight automation.","bl":false},{"id":"305","text":"Confer with clients to discuss and determine layout design.","b":"a","r":"AI drafts the concepts before the meeting; understanding what the client actually wants stays human.","bl":false},{"id":"23971","text":"Research the target audience of projects.","b":"a","r":"AI synthesises audience research instantly; interpreting it for this brand stays human.","bl":false},{"id":"303","text":"Draw and print charts, graphs, illustrations, and other artwork, using computer.","b":"x","r":"Charts and standard artwork generate from data and templates.","bl":false},{"id":"302","text":"Mark up, paste, and assemble final layouts to prepare layouts for printer.","b":"x","r":"Assembling final layouts for print is automated prepress.","bl":false},{"id":"309","text":"Study illustrations and photographs to plan presentation of materials, products, or services.","b":"a","r":"AI curates references and moodboards; the presentation concept stays human.","bl":false},{"id":"15228","text":"Maintain archive of images, photos, or previous work products.","b":"x","r":"Asset archiving and tagging is automated the moment files land.","bl":false},{"id":"310","text":"Prepare notes and instructions for workers who assemble and prepare final layouts for printing.","b":"a","r":"AI generates the production specs; instructing the people who finish the work stays human.","bl":false},{"id":"308","text":"Prepare illustrations or rough sketches of material, discussing them with clients or supervisors and making necessary changes.","b":"a","r":"AI produces the roughs in seconds; discussing and iterating with the client stays human.","bl":false},{"id":"15229","text":"Research new software or design concepts.","b":"a","r":"AI surfaces new tools and styles continuously; judging what serves the work stays human.","bl":false},{"id":"313","text":"Produce still and animated graphics for on-air and taped portions of television news broadcasts, using electronic video equipment.","b":"a","r":"AI generates the broadcast graphics variants; the designer art directs the output.","bl":false}],"new":[{"t":"Art direct AI image generation instead of drawing from scratch","r":"The skill moves from hand to eye: directing, selecting, correcting."},{"t":"Verify AI-generated assets for brand and legal safety","r":"Models borrow. Someone must check what the output resembles."},{"t":"Build and maintain the brand's generation system","r":"Templates, prompts and guardrails become the design system itself."},{"t":"Correct the almost-right details AI always gets wrong","r":"Hands, text, logos, spacing. Finishing is a human craft."}],"moves":{"u":"Pure production tasks are gone as value. Taste, client handling and finishing are the career now.","a":"Direct the machine: more concepts, faster iteration, human selection. Output per designer explodes.","x":"Automate prepress, archiving and standard artwork completely.","n":"Own AI art direction and asset safety. The designer who can run the generation system runs the studio."},"take":"No craft role illustrates augmentation better: production collapses, direction survives. The designer who draws is exposed; the designer with taste, client skills and AI direction becomes dramatically more productive."},{"slug":"hr-assistants","soc":"43-4161.00","cluster":"people","label":"HR Assistants","onetTitle":"Human Resources Assistants, Except Payroll and Timekeeping","basis":null,"counts":{"u":0,"a":2,"x":12,"n":4},"tasks":[{"id":"18572","text":"Process, verify, and maintain personnel related documentation, including staffing, recruitment, training, grievances, performance evaluations, classifications, and employee leaves of absence.","b":"x","r":"Processing and verifying documents against rules is volume work. Automation with exception flags.","bl":false},{"id":"2689","text":"Record data for each employee, including such information as addresses, weekly earnings, absences, amount of sales or production, supervisory reports on performance, and dates of and reasons for terminations.","b":"x","r":"Recording structured employee data is the definition of digital in, digital out.","bl":false},{"id":"2687","text":"Explain company personnel policies, benefits, and procedures to employees or job applicants.","b":"x","r":"A grounded assistant answers routine policy and benefits questions instantly, any hour.","bl":true},{"id":"2702","text":"Provide assistance in administering employee benefit programs and worker's compensation plans.","b":"x","r":"Benefits administration runs on rules and forms. Software handles it, people handle exceptions.","bl":false},{"id":"2691","text":"Answer questions regarding examinations, eligibility, salaries, benefits, and other pertinent information.","b":"x","r":"Eligibility and salary questions have definite answers. A self serve layer takes these.","bl":false},{"id":"21013","text":"Prepare and set up for new employee orientations.","b":"x","r":"Orientation logistics: scheduling, materials, rooms, links. A workflow, not a conversation.","bl":false},{"id":"2693","text":"Gather personnel records from other departments or employees.","b":"x","r":"Gathering records from departments is a system integration, not a task for a person.","bl":false},{"id":"2692","text":"Examine employee files to answer inquiries and provide information for personnel actions.","b":"x","r":"File lookups to answer enquiries are search, and search is what machines do best.","bl":false},{"id":"2694","text":"Search employee files to obtain information for authorized persons and organizations, such as credit bureaus and finance companies.","b":"x","r":"Authorised record retrieval for third parties is a controlled, auditable automated flow.","bl":false},{"id":"2697","text":"Compile and prepare reports and documents pertaining to personnel activities.","b":"x","r":"Compiling standard reports from personnel data is scheduled automation.","bl":false},{"id":"2695","text":"Interview job applicants to obtain and verify information used to screen and evaluate them.","b":"a","r":"AI captures and verifies the information; the assistant handles the human moments in the interview.","bl":false},{"id":"2690","text":"Process and review employment applications to evaluate qualifications or eligibility of applicants.","b":"x","r":"Reviewing applications against criteria is screening, and screening automates.","bl":false},{"id":"2698","text":"Inform job applicants of their acceptance or rejection of employment.","b":"x","r":"Acceptance and rejection notifications should be instant, templated and kind. Automate with care.","bl":false},{"id":"2699","text":"Select applicants meeting specified job requirements and refer them to hiring personnel.","b":"a","r":"AI matches applications to requirements; the referral decision keeps a human in the loop.","bl":true}],"new":[{"t":"Run the exception queue the automation flags","r":"The work does not vanish; it concentrates into the cases the rules cannot handle."},{"t":"Quality-check AI-processed records and documents","r":"Spot checks replace processing. Accuracy becomes the job."},{"t":"Handle the employees the chatbot cannot help","r":"What remains is complex, sensitive or upset. It needs more skill, not less."},{"t":"Own HRIS data hygiene so AI answers stay right","r":"Every wrong record becomes a wrong answer at scale."}],"moves":{"u":"Nothing in this bundle is untouched. That is the honest finding, and it demands a plan, not panic.","a":"Keep the human in the interviews and referrals. Judgement about people stays with people.","x":"Automate the documentation, records and routine answers, and reinvest the hours in exception handling and service quality.","n":"The role evolves into AI supervision: exceptions, quality checks, data hygiene. Start that training now."},"take":"No role in this index is more exposed. Almost every task is rules based volume work that software already does well. The honest read: this job does not disappear, it transforms into supervising the automation, and there will be fewer seats doing it."},{"slug":"hr-business-partner","soc":"13-1071.00+11-3121.00","cluster":"people","label":"HR Business Partner","onetTitle":"HR Business Partner","basis":"A composite role: every core task from HR Specialists, plus the five HR Manager tasks that carry the advisory relationship a business partner actually holds.","counts":{"u":5,"a":14,"x":5,"n":5},"tasks":[{"id":"18861","text":"Interpret and explain human resources policies, procedures, laws, standards, or regulations.","b":"a","r":"AI drafts the answer grounded in the handbook; the specialist handles the nuance and the exception.","bl":false},{"id":"18859","text":"Hire employees and process hiring-related paperwork.","b":"x","r":"High volume processing against a checklist. The decision sits elsewhere; the paperwork does not need a person.","bl":false},{"id":"18864","text":"Maintain current knowledge of Equal Employment Opportunity (EEO) and affirmative action guidelines and laws, such as the Americans with Disabilities Act (ADA).","b":"a","r":"AI tracks legal change and summarises it; judging what applies here stays human.","bl":false},{"id":"18866","text":"Prepare or maintain employment records related to events, such as hiring, termination, leaves, transfers, or promotions, using human resources management system software.","b":"x","r":"Record keeping in the HRIS is digital in, digital out. Automate it and audit samples.","bl":false},{"id":"18852","text":"Address employee relations issues, such as harassment allegations, work complaints, or other employee concerns.","b":"u","r":"Harassment allegations and complaints need confidentiality, trust and accountability in the room.","bl":false},{"id":"18868","text":"Review employment applications and job orders to match applicants with job requirements.","b":"x","r":"Screening applications against stated requirements is rules based volume work. Audit it for bias monthly.","bl":true},{"id":"18860","text":"Inform job applicants of details such as duties and responsibilities, compensation, benefits, schedules, working conditions, or promotion opportunities.","b":"a","r":"AI answers the standard questions instantly; the specialist sells the role to the candidates who matter.","bl":false},{"id":"18871","text":"Select qualified job applicants or refer them to managers, making hiring recommendations when appropriate.","b":"u","r":"The hiring recommendation carries the organisation's judgement about a person. It stays human.","bl":false},{"id":"18870","text":"Schedule or conduct new employee orientations.","b":"a","r":"AI builds the schedule and the materials; the specialist hosts and reads the room.","bl":false},{"id":"18863","text":"Maintain and update human resources documents, such as organizational charts, employee handbooks or directories, or performance evaluation forms.","b":"x","r":"Org charts, handbooks and directories update themselves once systems are connected.","bl":false},{"id":"18856","text":"Confer with management to develop or implement personnel policies or procedures.","b":"a","r":"AI drafts policy options and impact notes; developing the actual policy with management stays human.","bl":false},{"id":"18857","text":"Contact job applicants to inform them of the status of their applications.","b":"x","r":"Status updates to applicants are the classic automated workflow, and candidates prefer instant.","bl":false},{"id":"18854","text":"Conduct exit interviews and ensure that necessary employment termination paperwork is completed.","b":"u","r":"The exit conversation stays human; the paperwork around it should not.","bl":false},{"id":"18862","text":"Interview job applicants to obtain information on work history, training, education, or job skills.","b":"a","r":"AI drafts questions and scores notes against criteria; the person reads the room.","bl":true},{"id":"18865","text":"Perform searches for qualified job candidates, using sources such as computer databases, networking, Internet recruiting resources, media advertisements, job fairs, recruiting firms, or employee referrals.","b":"a","r":"AI finds and ranks candidates at scale; the specialist judges fit and makes the approach.","bl":false},{"id":"18867","text":"Provide management with information or training related to interviewing, performance appraisals, counseling techniques, or documentation of performance issues.","b":"a","r":"AI assembles the training content; coaching managers through real cases stays human.","bl":false},{"id":"18853","text":"Analyze employment-related data and prepare required reports.","b":"a","r":"AI prepares the analysis and the report; the specialist decides what it means and what to do.","bl":false},{"id":"18872","text":"Advise management on organizing, preparing, or implementing recruiting or retention programs.","b":"a","r":"AI models retention patterns; advising management on programmes stays judgement work.","bl":false},{"id":"18858","text":"Develop or implement recruiting strategies to meet current or anticipated staffing needs.","b":"a","r":"AI drafts the strategy from market data; choosing where to fish stays human.","bl":false},{"id":"990","text":"Serve as a link between management and employees by handling questions, interpreting and administering contracts and helping resolve work-related problems.","b":"u","r":"The trusted link between managers and staff lives in the conversation, not the summary.","bl":false},{"id":"987","text":"Advise managers on organizational policy matters, such as equal employment opportunity and sexual harassment, and recommend needed changes.","b":"a","r":"AI drafts the policy position and flags the risk; the manager judges what fits this organisation.","bl":false},{"id":"988","text":"Analyze and modify compensation and benefits policies to establish competitive programs and ensure compliance with legal requirements.","b":"a","r":"AI models the market data and drafts options; competitiveness and fairness stay human calls.","bl":false},{"id":"996","text":"Conduct exit interviews to identify reasons for employee termination.","b":"u","r":"An exit interview works because a person asks and a person hears the answer.","bl":false},{"id":"984","text":"Allocate human resources, ensuring appropriate matches between personnel.","b":"a","r":"AI proposes matches from skills data; allocation among real people stays a human judgement.","bl":false}],"new":[{"t":"Audit AI-drafted policy advice before it reaches staff","r":"The business partner is the last human checkpoint before advice lands."},{"t":"Check AI screening for bias on every hiring round","r":"The screener makes a thousand quiet decisions. Someone must audit them."},{"t":"Validate AI-generated workforce reports before they go upward","r":"A plausible chart with a wrong join poisons a leadership decision."},{"t":"Coach managers to work with the HR assistant well","r":"Adoption fails at the line manager. The HRBP becomes the coach."},{"t":"Own the people data the AI reasons over","r":"Bad records become bad advice at scale. Data quality is now advisory work."}],"moves":{"u":"Ring fence the conversations. Complaints, recommendations and exits are where trust is built or lost.","a":"Make the AI first draft the default for screening, sourcing, analysis and reporting. Review, then send.","x":"Automate status updates, records and application processing end to end, with bias and exception audits.","n":"Build the checking habit now. Every AI output that touches a person needs a named human verifier."},"take":"The business partner model was built to trade admin for advice. AI finally enforces the deal: the admin evaporates whether the HRBP likes it or not, and the role becomes advice, judgement and AI quality control, or it becomes nothing."},{"slug":"hr-managers","soc":"11-3121.00","cluster":"people","label":"HR Managers","onetTitle":"Human Resources Managers","basis":null,"counts":{"u":7,"a":10,"x":3,"n":5},"tasks":[{"id":"990","text":"Serve as a link between management and employees by handling questions, interpreting and administering contracts and helping resolve work-related problems.","b":"u","r":"The trusted link between managers and staff lives in the conversation, not the summary.","bl":false},{"id":"991","text":"Plan, direct, supervise, and coordinate work activities of subordinates and staff relating to employment, compensation, labor relations, and employee relations.","b":"u","r":"Directing people is the job. AI can brief the manager; it cannot lead the team.","bl":false},{"id":"986","text":"Perform difficult staffing duties, including dealing with understaffing, refereeing disputes, firing employees, and administering disciplinary procedures.","b":"u","r":"Firing, disputes and discipline carry legal accountability and human weight. No delegation.","bl":false},{"id":"998","text":"Represent organization at personnel-related hearings and investigations.","b":"u","r":"Representation at hearings is advocacy under oath. Presence is the task.","bl":false},{"id":"999","text":"Negotiate bargaining agreements and help interpret labor contracts.","b":"u","r":"Negotiation reads the room and carries the relationship. AI prepares, the person settles.","bl":true},{"id":"987","text":"Advise managers on organizational policy matters, such as equal employment opportunity and sexual harassment, and recommend needed changes.","b":"a","r":"AI drafts the policy position and flags the risk; the manager judges what fits this organisation.","bl":false},{"id":"989","text":"Plan and conduct new employee orientation to foster positive attitude toward organizational objectives.","b":"a","r":"AI personalises orientation content and scheduling; the welcome still needs a face.","bl":false},{"id":"988","text":"Analyze and modify compensation and benefits policies to establish competitive programs and ensure compliance with legal requirements.","b":"a","r":"AI models the market data and drafts options; competitiveness and fairness stay human calls.","bl":false},{"id":"983","text":"Identify staff vacancies and recruit, interview, and select applicants.","b":"a","r":"AI screens and shortlists; interviewing and the selection call stay with the manager.","bl":true},{"id":"997","text":"Investigate and report on industrial accidents for insurance carriers.","b":"a","r":"AI drafts the report from the facts; the investigation and its judgements stay human.","bl":false},{"id":"994","text":"Analyze statistical data and reports to identify and determine causes of personnel problems and develop recommendations for improvement of organization's personnel policies and practices.","b":"a","r":"AI crunches the personnel data; deciding what it means for policy is the manager's work.","bl":false},{"id":"1001","text":"Prepare and follow budgets for personnel operations.","b":"a","r":"AI builds the draft budget and tracks variance; the trade offs stay with the person.","bl":false},{"id":"982","text":"Administer compensation, benefits, and performance management systems, and safety and recreation programs.","b":"x","r":"Rule based administration of schemes and systems. Software runs it, people handle exceptions.","bl":false},{"id":"993","text":"Maintain records and compile statistical reports concerning personnel-related data such as hires, transfers, performance appraisals, and absenteeism rates.","b":"x","r":"High volume record keeping and statistical reporting. Digital in, digital out.","bl":false},{"id":"985","text":"Provide current and prospective employees with information about policies, job duties, working conditions, wages, opportunities for promotion, and employee benefits.","b":"x","r":"Routine policy and benefits questions are exactly what a well grounded assistant answers.","bl":false},{"id":"995","text":"Plan, organize, direct, control, or coordinate the personnel, training, or labor relations activities of an organization.","b":"u","r":"Setting the direction of the people function is accountability, not throughput.","bl":false},{"id":"996","text":"Conduct exit interviews to identify reasons for employee termination.","b":"u","r":"An exit interview works because a person asks and a person hears the answer.","bl":false},{"id":"1003","text":"Oversee the evaluation, classification, and rating of occupations and job positions.","b":"a","r":"AI drafts job evaluations and grading comparisons; the manager owns the structure.","bl":false},{"id":"992","text":"Analyze training needs to design employee development, language training, and health and safety programs.","b":"a","r":"AI analyses skills gaps and drafts programme designs; the manager chooses what the business needs.","bl":false},{"id":"984","text":"Allocate human resources, ensuring appropriate matches between personnel.","b":"a","r":"AI proposes matches from skills data; allocation among real people stays a human judgement.","bl":false}],"new":[{"t":"Audit AI screening and shortlisting for adverse impact","r":"Regulators and candidates will both ask. Someone senior must be able to answer."},{"t":"Validate AI-drafted policy guidance before it reaches staff","r":"A wrong answer about harassment or entitlement lands on the employer, not the vendor."},{"t":"Own the HR assistant's guardrails and escalation rules","r":"Deciding what the tool may never answer is a new and serious responsibility."},{"t":"Coach managers to work with AI rather than around it","r":"Adoption fails at the line manager. The HR manager becomes the coach."},{"t":"Review algorithmic decisions on pay, scheduling and performance","r":"Every automated recommendation needs a human who can override and explain."}],"moves":{"u":"Protect diary time for these. As administration shrinks, the value of the role concentrates in the conversations only a trusted person can have.","a":"Build the AI first draft into the weekly routine. The job shifts from producing the analysis to judging it.","x":"Move recording, reporting and routine answers into systems with a monthly exception review. Stop paying senior salaries for data entry.","n":"Name an owner for AI quality now. The first audit question is coming either way."},"take":"The HR manager's week splits cleanly: the paperwork collapses into systems, the advisory work gets faster, and the disputes, hearings and hard conversations stay exactly where they were. The role loses admin and gains consequence."},{"slug":"hr-specialists","soc":"13-1071.00","cluster":"people","label":"HR Specialists","onetTitle":"Human Resources Specialists","basis":null,"counts":{"u":3,"a":11,"x":5,"n":5},"tasks":[{"id":"18861","text":"Interpret and explain human resources policies, procedures, laws, standards, or regulations.","b":"a","r":"AI drafts the answer grounded in the handbook; the specialist handles the nuance and the exception.","bl":false},{"id":"18859","text":"Hire employees and process hiring-related paperwork.","b":"x","r":"High volume processing against a checklist. The decision sits elsewhere; the paperwork does not need a person.","bl":false},{"id":"18864","text":"Maintain current knowledge of Equal Employment Opportunity (EEO) and affirmative action guidelines and laws, such as the Americans with Disabilities Act (ADA).","b":"a","r":"AI tracks legal change and summarises it; judging what applies here stays human.","bl":false},{"id":"18866","text":"Prepare or maintain employment records related to events, such as hiring, termination, leaves, transfers, or promotions, using human resources management system software.","b":"x","r":"Record keeping in the HRIS is digital in, digital out. Automate it and audit samples.","bl":false},{"id":"18852","text":"Address employee relations issues, such as harassment allegations, work complaints, or other employee concerns.","b":"u","r":"Harassment allegations and complaints need confidentiality, trust and accountability in the room.","bl":false},{"id":"18868","text":"Review employment applications and job orders to match applicants with job requirements.","b":"x","r":"Screening applications against stated requirements is rules based volume work. Audit it for bias monthly.","bl":true},{"id":"18860","text":"Inform job applicants of details such as duties and responsibilities, compensation, benefits, schedules, working conditions, or promotion opportunities.","b":"a","r":"AI answers the standard questions instantly; the specialist sells the role to the candidates who matter.","bl":false},{"id":"18871","text":"Select qualified job applicants or refer them to managers, making hiring recommendations when appropriate.","b":"u","r":"The hiring recommendation carries the organisation's judgement about a person. It stays human.","bl":false},{"id":"18870","text":"Schedule or conduct new employee orientations.","b":"a","r":"AI builds the schedule and the materials; the specialist hosts and reads the room.","bl":false},{"id":"18863","text":"Maintain and update human resources documents, such as organizational charts, employee handbooks or directories, or performance evaluation forms.","b":"x","r":"Org charts, handbooks and directories update themselves once systems are connected.","bl":false},{"id":"18856","text":"Confer with management to develop or implement personnel policies or procedures.","b":"a","r":"AI drafts policy options and impact notes; developing the actual policy with management stays human.","bl":false},{"id":"18857","text":"Contact job applicants to inform them of the status of their applications.","b":"x","r":"Status updates to applicants are the classic automated workflow, and candidates prefer instant.","bl":false},{"id":"18854","text":"Conduct exit interviews and ensure that necessary employment termination paperwork is completed.","b":"u","r":"The exit conversation stays human; the paperwork around it should not.","bl":false},{"id":"18862","text":"Interview job applicants to obtain information on work history, training, education, or job skills.","b":"a","r":"AI drafts questions and scores notes against criteria; the person reads the room.","bl":true},{"id":"18865","text":"Perform searches for qualified job candidates, using sources such as computer databases, networking, Internet recruiting resources, media advertisements, job fairs, recruiting firms, or employee referrals.","b":"a","r":"AI finds and ranks candidates at scale; the specialist judges fit and makes the approach.","bl":false},{"id":"18867","text":"Provide management with information or training related to interviewing, performance appraisals, counseling techniques, or documentation of performance issues.","b":"a","r":"AI assembles the training content; coaching managers through real cases stays human.","bl":false},{"id":"18853","text":"Analyze employment-related data and prepare required reports.","b":"a","r":"AI prepares the analysis and the report; the specialist decides what it means and what to do.","bl":false},{"id":"18872","text":"Advise management on organizing, preparing, or implementing recruiting or retention programs.","b":"a","r":"AI models retention patterns; advising management on programmes stays judgement work.","bl":false},{"id":"18858","text":"Develop or implement recruiting strategies to meet current or anticipated staffing needs.","b":"a","r":"AI drafts the strategy from market data; choosing where to fish stays human.","bl":false}],"new":[{"t":"Audit AI shortlists for adverse impact before interviews are booked","r":"The screener makes a thousand quiet decisions. Someone must check whom it filters out."},{"t":"Verify AI-drafted policy answers before employees rely on them","r":"One confident wrong answer about entitlement becomes a grievance."},{"t":"Manage the candidate chatbot's tone, limits and handoffs","r":"The bot is now the first impression of the employer brand."},{"t":"Validate AI-generated workforce reports before they go upward","r":"A plausible chart with a wrong join poisons a board decision."},{"t":"Keep the knowledge base the AI answers from current and correct","r":"The assistant is only as good as what it is fed. Feeding it is a job."}],"moves":{"u":"Ring fence the conversations. Complaints, recommendations and exits are where trust is built or lost.","a":"Make the AI first draft the default for screening, sourcing, analysis and reporting. Review, then send.","x":"Automate status updates, records and application processing end to end, with bias and exception audits.","n":"Build the checking habit now. Every AI output that touches a person needs a named human verifier."},"take":"This is the engine room role, and the engine is changing. Sourcing, screening, records and status updates automate; the specialist who thrives moves up the judgement ladder into employee relations, advisory work and AI quality control."},{"slug":"labor-relations-specialists","soc":"13-1075.00","cluster":"people","label":"Labor Relations Specialists","onetTitle":"Labor Relations Specialists","basis":null,"counts":{"u":4,"a":14,"x":2,"n":4},"tasks":[{"id":"18886","text":"Negotiate collective bargaining agreements.","b":"u","r":"Collective bargaining is trust, pressure and timing across a table. The person negotiates.","bl":false},{"id":"18883","text":"Investigate and evaluate union complaints or arguments to determine viability.","b":"a","r":"AI summarises the complaint file and finds precedents; judging viability stays human.","bl":false},{"id":"18890","text":"Propose resolutions for collective bargaining or other labor or contract negotiations.","b":"a","r":"AI models settlement options and their costs; choosing what to propose is strategy.","bl":false},{"id":"18879","text":"Draft contract proposals or counter-proposals for collective bargaining or other labor negotiations.","b":"a","r":"AI drafts proposals and counter-proposals from positions; the specialist shapes the play.","bl":false},{"id":"18882","text":"Interpret contractual agreements for employers and employees engaged in collective bargaining or other labor relations processes.","b":"a","r":"AI retrieves clause language and past interpretations; applying it to this dispute stays human.","bl":false},{"id":"18900","text":"Prepare evidence for disciplinary hearings, including preparing witnesses to testify.","b":"a","r":"AI assembles the evidence bundle; preparing a witness is rehearsal between people.","bl":false},{"id":"18884","text":"Mediate discussions between employer and employee representatives in attempt to reconcile differences.","b":"u","r":"Mediation works because a neutral human holds the room. No shortcut.","bl":false},{"id":"18893","text":"Review employer practices or employee data to ensure compliance with contracts on matters such as wages, hours, or conditions of employment.","b":"a","r":"AI scans practice and data against the contract; the compliance judgement stays human.","bl":false},{"id":"18891","text":"Recommend collective bargaining strategies, goals, or objectives.","b":"a","r":"AI wargames strategies against past outcomes; recommending one is judgement.","bl":false},{"id":"18885","text":"Monitor company or workforce adherence to labor agreements.","b":"x","r":"Continuous monitoring of adherence is exactly what connected systems do without tiring.","bl":true},{"id":"18878","text":"Call or meet with union, company, government, or other interested parties to discuss labor relations matters, such as contract negotiations or grievances.","b":"u","r":"The relationship with union and government counterparts is the job.","bl":false},{"id":"18896","text":"Assess risk levels associated with collective bargaining strategies.","b":"a","r":"AI scores risk against precedent and exposure; appetite stays human.","bl":false},{"id":"18889","text":"Present the position of the company or of labor during arbitration or other labor negotiations.","b":"u","r":"Advocacy at arbitration is performance and persuasion under scrutiny.","bl":false},{"id":"18881","text":"Identify alternatives to proposals of unions, employees, companies, or government agencies.","b":"a","r":"AI generates option sets; selecting the viable ones needs the context only the specialist holds.","bl":false},{"id":"18880","text":"Draft rules or regulations to govern collective bargaining activities in collaboration with company, government, or employee representatives.","b":"a","r":"AI drafts the rule language; agreeing it with the parties is negotiation.","bl":false},{"id":"18902","text":"Research case law or outcomes of previous case hearings.","b":"a","r":"AI searches case law in seconds; weighing what it means for this case is the craft.","bl":false},{"id":"18895","text":"Write letters related to labor relations activities, such as letters to amend collective bargaining agreements, letters of dispute or conciliation, or letters to seek clarification of contract terms.","b":"a","r":"AI drafts the letters; tone and legal precision get a human pass before sending.","bl":false},{"id":"18894","text":"Schedule or coordinate the details of grievance hearings or other meetings.","b":"x","r":"Scheduling hearings and coordinating details is pure logistics.","bl":false},{"id":"18892","text":"Review and approve employee disciplinary actions, such as written reprimands, suspensions, or terminations.","b":"a","r":"AI checks disciplinary actions for consistency; approving them carries accountability.","bl":true},{"id":"18903","text":"Select mediators or arbitrators for labor disputes or contract negotiations.","b":"a","r":"AI profiles candidates from past outcomes; the choice shapes the dispute, so it stays human.","bl":false}],"new":[{"t":"Model the cost of union proposals before anything is tabled","r":"Negotiating blind is over. The side with the better model concedes less."},{"t":"Audit AI contract analysis against the actual agreement language","r":"A hallucinated clause in a grievance response is a credibility catastrophe."},{"t":"Track algorithmic management as a bargaining issue","r":"Scheduling, monitoring and pay algorithms are the new frontier of labour relations."},{"t":"Build AI precedent packs for negotiators","r":"Every past settlement, indexed and searchable, changes what preparation means."}],"moves":{"u":"Protect the table work. Negotiation, mediation and advocacy are where this role earns its keep.","a":"Let AI do the research, drafting and modelling. Arrive at every discussion better prepared than the other side.","x":"Automate monitoring and scheduling. The hours recovered go into preparation and relationships.","n":"Get ahead of algorithmic management. It will be on the bargaining agenda within a year, ready or not."},"take":"The research and drafting load collapses, and the human core (negotiation, mediation, advocacy) barely changes. The prepared side wins more often, and AI just made preparation cheap."},{"slug":"lawyers","soc":"23-1011.00","cluster":"knowledge","label":"Lawyers","onetTitle":"Lawyers","basis":null,"counts":{"u":1,"a":14,"x":0,"n":4},"tasks":[{"id":"3774","text":"Interpret laws, rulings and regulations for individuals and businesses.","b":"a","r":"AI retrieves the law and drafts the interpretation; advising this client on this situation carries liability.","bl":false},{"id":"3775","text":"Analyze the probable outcomes of cases, using knowledge of legal precedents.","b":"a","r":"AI analyses precedent outcomes at scale; the probabilistic call on a live case is professional judgement.","bl":false},{"id":"3778","text":"Gather evidence to formulate defense or to initiate legal actions by such means as interviewing clients and witnesses to ascertain the facts of a case.","b":"a","r":"AI organises and searches the evidence; interviewing clients and witnesses is trust work.","bl":false},{"id":"3779","text":"Represent clients in court or before government agencies.","b":"u","r":"Advocacy in court is performance, persuasion and accountability before a judge.","bl":false},{"id":"3777","text":"Evaluate findings and develop strategies and arguments in preparation for presentation of cases.","b":"a","r":"AI drafts the strategy options from precedent; the strategy for this client stays human.","bl":false},{"id":"3773","text":"Advise clients concerning business transactions, claim liability, advisability of prosecuting or defending lawsuits, or legal rights and obligations.","b":"a","r":"AI prepares the analysis; the advice a client bets a business on needs a named human behind it.","bl":false},{"id":"3780","text":"Examine legal data to determine advisability of defending or prosecuting lawsuit.","b":"a","r":"AI researches the precedents exhaustively; the advisability judgement stays human.","bl":false},{"id":"20877","text":"Prepare, draft, and review legal documents, such as wills, deeds, patent applications, mortgages, leases, and contracts.","b":"a","r":"AI drafts the documents in seconds; reviewing them before signature is where the value moved.","bl":true},{"id":"3783","text":"Study Constitution, statutes, decisions, regulations, and ordinances of quasi-judicial bodies to determine ramifications for cases.","b":"a","r":"AI tracks and summarises every relevant ruling; weighing ramifications for this case stays human.","bl":false},{"id":"3786","text":"Negotiate settlements of civil disputes.","b":"a","r":"AI models settlement ranges; the negotiation itself reads the other side.","bl":false},{"id":"3789","text":"Supervise legal assistants.","b":"a","r":"AI drafts the supervision briefs; developing junior lawyers is mentorship.","bl":false},{"id":"23992","text":"Negotiate contractual agreements.","b":"a","r":"AI drafts and marks up agreements; the negotiation and the final positions stay human.","bl":false},{"id":"3787","text":"Confer with colleagues with specialties in appropriate areas of legal issue to establish and verify bases for legal proceedings.","b":"a","r":"AI does the preliminary research; conferring with specialists is professional judgement shared.","bl":false},{"id":"3788","text":"Search for and examine public and other legal records to write opinions or establish ownership.","b":"a","r":"AI searches the records exhaustively; establishing ownership conclusions carries liability.","bl":true},{"id":"3790","text":"Perform administrative and management functions related to the practice of law.","b":"a","r":"AI handles the admin drafts; running the practice is leadership.","bl":false}],"new":[{"t":"Verify every AI citation before it touches a filing","r":"Courts now sanction lawyers for hallucinated citations. Verification is survival."},{"t":"Audit AI contract review against what a partner would catch","r":"The tool misses differently than a tired associate. Learn its blind spots."},{"t":"Supervise the AI-first-draft workflow and its reviewers","r":"Leverage changes shape: fewer juniors typing, more seniors checking."},{"t":"Advise clients on their own AI legal exposure","r":"Employment, IP and liability questions about AI are the new practice area."}],"moves":{"u":"Court, clients and counsel stay human. The robe, the room and the relationship are the moat.","a":"Let AI draft and research at machine speed. Bill for judgement, not for typing.","x":"Almost nothing here is pure automation: legal work carries accountability. That is the finding.","n":"Build the verification discipline. The firms that check AI output rigorously will eat the ones that do not."},"take":"Research and drafting (the billable bulk of junior work) compress to minutes, while advocacy, advice and negotiation hold. The leverage model of law firms is under direct threat; the partner judgement at the top is not."},{"slug":"management-analysts","soc":"13-1111.00","cluster":"people","label":"Management Analysts / Org Designers","onetTitle":"Management Analysts","basis":null,"counts":{"u":1,"a":8,"x":2,"n":4},"tasks":[{"id":"7276","text":"Gather and organize information on problems or procedures.","b":"a","r":"AI ingests documents and data at scale; knowing which problems matter needs client context.","bl":false},{"id":"7278","text":"Confer with personnel concerned to ensure successful functioning of newly implemented systems or procedures.","b":"a","r":"AI monitors adoption metrics; making a new system actually stick is persuasion, person to person.","bl":false},{"id":"7277","text":"Analyze data gathered and develop solutions or alternative methods of proceeding.","b":"a","r":"AI generates solution options and models them; choosing one for this organisation is the craft.","bl":false},{"id":"7282","text":"Document findings of study and prepare recommendations for implementation of new systems, procedures, or organizational changes.","b":"a","r":"AI drafts the report and recommendations; the analyst owns the argument and the client's trust.","bl":false},{"id":"7285","text":"Plan study of work problems and procedures, such as organizational change, communications, information flow, integrated production methods, inventory control, or cost analysis.","b":"a","r":"AI structures the study plan from past engagements; framing the real problem stays human.","bl":false},{"id":"7281","text":"Interview personnel and conduct on-site observation to ascertain unit functions, work performed, and methods, equipment, and personnel used.","b":"u","r":"Interviewing staff and observing work on site is how the truth surfaces. Presence is the method.","bl":false},{"id":"7283","text":"Prepare manuals and train workers in use of new forms, reports, procedures or equipment, according to organizational policy.","b":"a","r":"AI drafts manuals and training materials; teaching sceptical users new ways stays human.","bl":true},{"id":"7280","text":"Review forms and reports and confer with management and users about format, distribution, and purpose, identifying problems and improvements.","b":"a","r":"AI reviews forms and flags redundancies; negotiating change with the people who use them is human.","bl":false},{"id":"7279","text":"Develop and implement records management program for filing, protection, and retrieval of records, and assure compliance with program.","b":"x","r":"Records management design and compliance is system configuration plus rules.","bl":true},{"id":"7284","text":"Design, evaluate, recommend, and approve changes of forms and reports.","b":"a","r":"AI drafts improved forms; approving changes that affect hundreds of users stays human.","bl":false},{"id":"7286","text":"Recommend purchase of storage equipment and design area layout to locate equipment in space available.","b":"x","r":"Layout and equipment optimisation is a solvable spatial problem.","bl":false}],"new":[{"t":"Verify AI-generated findings against the raw interviews","r":"A plausible synthesis that misquotes the client ends the engagement."},{"t":"Design the AI-augmented operating model, not just the process map","r":"Clients now ask which tasks stay human. This index is the answer."},{"t":"Run continuous process mining instead of periodic studies","r":"The diagnostic becomes live, and someone must interpret it."},{"t":"Audit the client's own AI deployments for task drift","r":"When tools silently change how work is done, someone maps the new reality."}],"moves":{"u":"Fieldwork is the moat. The interview and the site visit surface what no dataset holds.","a":"Let AI accelerate the analysis and the drafting. Sell the judgement, not the slide production.","x":"Automate records and layout optimisation work. It was never the value.","n":"Pivot the offer: clients need task level AI redesign, and this role is built to deliver it."},"take":"The analysis factory (gather, model, document) compresses dramatically. What clients pay for concentrates into fieldwork, judgement and change that sticks. This role should be selling AI redesign right now."},{"slug":"market-research-analysts","soc":"13-1161.00","cluster":"knowledge","label":"Market Research Analysts","onetTitle":"Market Research Analysts and Marketing Specialists","basis":null,"counts":{"u":0,"a":12,"x":1,"n":4},"tasks":[{"id":"5434","text":"Prepare reports of findings, illustrating data graphically and translating complex findings into written text.","b":"a","r":"AI drafts the report and the charts; the analyst owns the story the data actually supports.","bl":false},{"id":"5433","text":"Collect and analyze data on customer demographics, preferences, needs, and buying habits to identify potential markets and factors affecting product demand.","b":"a","r":"AI crunches demographics and behaviour at scale; framing what to look for stays human.","bl":false},{"id":"5439","text":"Conduct research on consumer opinions and marketing strategies, collaborating with marketing professionals, statisticians, pollsters, and other professionals.","b":"a","r":"AI synthesises findings across sources; designing the research with colleagues stays human.","bl":false},{"id":"5435","text":"Measure and assess customer and employee satisfaction.","b":"a","r":"AI analyses satisfaction data continuously; deciding what to do about it stays human.","bl":false},{"id":"5443","text":"Devise and evaluate methods and procedures for collecting data, such as surveys, opinion polls, or questionnaires, or arrange to obtain existing data.","b":"a","r":"AI drafts the instrument and tests it; wording that real humans answer honestly needs craft.","bl":true},{"id":"5438","text":"Measure the effectiveness of marketing, advertising, and communications programs and strategies.","b":"a","r":"AI measures programme performance continuously; judging cause versus correlation stays human.","bl":true},{"id":"5437","text":"Seek and provide information to help companies determine their position in the marketplace.","b":"a","r":"AI assembles the positioning evidence; advising where to compete is judgement.","bl":false},{"id":"5436","text":"Forecast and track marketing and sales trends, analyzing collected data.","b":"a","r":"AI tracks and forecasts trends from every feed; calling the trend that matters is the edge.","bl":false},{"id":"5441","text":"Gather data on competitors and analyze their prices, sales, and method of marketing and distribution.","b":"a","r":"AI monitors competitors and prices in real time; interpreting their intent stays human.","bl":false},{"id":"5442","text":"Monitor industry statistics and follow trends in trade literature.","b":"x","r":"Following trade statistics and literature is a feed. AI reads it all and briefs you.","bl":false},{"id":"5440","text":"Attend staff conferences to provide management with information and proposals concerning the promotion, distribution, design, and pricing of company products or services.","b":"a","r":"AI prepares the briefing; presenting to management and defending it stays human.","bl":false},{"id":"5445","text":"Direct trained survey interviewers.","b":"a","r":"AI drafts the interview scripts and checks quality; directing fieldworkers stays human.","bl":false},{"id":"5444","text":"Develop and implement procedures for identifying advertising needs.","b":"a","r":"AI drafts the procedures from best practice; adapting them to this business stays human.","bl":false}],"new":[{"t":"Audit AI-synthesised insights against the raw data","r":"One hallucinated data point in a board pack destroys the function's credibility."},{"t":"Run synthetic respondents alongside real panels","r":"AI panels are fast and cheap; knowing when they lie is new expertise."},{"t":"Build the always-on competitor intelligence feed","r":"Monitoring becomes continuous; someone curates what matters."},{"t":"Verify AI survey analysis for leading-question bias","r":"The tool inherits the instrument's flaws and amplifies them."}],"moves":{"u":"Research design and client persuasion stay human. Asking the right question is still the whole game.","a":"Let AI read everything and draft everything. Analysts shift from gathering to judging.","x":"Automate literature monitoring and data pulls. The reading week is over.","n":"Own synthetic data literacy: when AI respondents help and when they mislead."},"take":"The gathering phase of research (weeks of reading, pulling, cleaning) compresses to hours. The role tilts hard toward design, interpretation and the sceptical verification of what the machine concludes."},{"slug":"marketing-managers","soc":"11-2021.00","cluster":"knowledge","label":"Marketing Managers","onetTitle":"Marketing Managers","basis":null,"counts":{"u":0,"a":13,"x":1,"n":4},"tasks":[{"id":"951","text":"Identify, develop, or evaluate marketing strategy, based on knowledge of establishment objectives, market characteristics, and cost and markup factors.","b":"a","r":"AI generates and tests strategy options against market data; choosing the bet stays human.","bl":false},{"id":"20709","text":"Formulate, direct, or coordinate marketing activities or policies to promote products or services, working with advertising or promotion managers.","b":"a","r":"AI drafts the campaign plans and coordinates the calendar; directing the function stays human.","bl":false},{"id":"952","text":"Evaluate the financial aspects of product development, such as budgets, expenditures, research and development appropriations, or return-on-investment and profit-loss projections.","b":"a","r":"AI models the ROI scenarios; committing budget to a product bet is a judgement call.","bl":true},{"id":"950","text":"Develop pricing strategies, balancing firm objectives and customer satisfaction.","b":"a","r":"AI optimises price against demand signals; balancing margin and brand stays human.","bl":false},{"id":"957","text":"Compile lists describing product or service offerings.","b":"x","r":"Compiling offering lists from product data is documentation. Generate it.","bl":false},{"id":"954","text":"Direct the hiring, training, or performance evaluations of marketing or sales staff and oversee their daily activities.","b":"a","r":"AI handles the evaluation data and training content; hiring and leading marketers stays human.","bl":false},{"id":"956","text":"Consult with product development personnel on product specifications, such as design, color, or packaging.","b":"a","r":"AI drafts specs and variations instantly; the taste call on design and packaging stays human.","bl":true},{"id":"958","text":"Use sales forecasting or strategic planning to ensure the sale and profitability of products, lines, or services, analyzing business developments and monitoring market trends.","b":"a","r":"AI forecasts and monitors continuously; the strategic interpretation is the manager's edge.","bl":false},{"id":"955","text":"Negotiate contracts with vendors or distributors to manage product distribution, establishing distribution networks or developing distribution strategies.","b":"a","r":"AI drafts contract positions and analyses terms; the negotiation itself stays across the table.","bl":false},{"id":"961","text":"Coordinate or participate in promotional activities or trade shows, working with developers, advertisers, or production managers, to market products or services.","b":"a","r":"AI coordinates the logistics and drafts the materials; working the show floor is human.","bl":false},{"id":"963","text":"Initiate market research studies, or analyze their findings.","b":"a","r":"AI designs the study and analyses results overnight; deciding what to ask stays human.","bl":false},{"id":"960","text":"Confer with legal staff to resolve problems, such as copyright infringement or royalty sharing with outside producers or distributors.","b":"a","r":"AI retrieves precedent and drafts positions; resolving IP disputes keeps counsel and judgement.","bl":false},{"id":"964","text":"Consult with buying personnel to gain advice regarding the types of products or services expected to be in demand.","b":"a","r":"AI synthesises buyer signals from every channel; the demand call stays human.","bl":false},{"id":"19502","text":"Consult with buying personnel to gain advice regarding environmentally sound or sustainable products.","b":"a","r":"AI researches sustainable options and certifications; judging what fits the brand stays human.","bl":false}],"new":[{"t":"Verify AI-generated campaign claims before they ship","r":"A fluent invented claim in a live campaign is a legal and brand event."},{"t":"Guard brand voice across a thousand AI-generated variants","r":"Volume is free now; consistency is the scarce asset."},{"t":"Run always-on synthetic market testing","r":"Testing concepts against AI panels before human panels changes the research budget."},{"t":"Audit AI personalisation for creepiness and compliance","r":"Just because the data allows it does not mean the brand survives it."}],"moves":{"u":"Leadership, negotiation and taste stay human. Marketing was always judgement plus volume; the volume is now free.","a":"Let AI draft, model and test everything. Direct more, produce nothing by hand.","x":"Automate compilation and reporting tasks immediately. Nobody will notice they are gone.","n":"Own brand safety in the age of infinite content. That is the new senior skill."},"take":"Production costs collapse and testing becomes nearly free, so the marketing manager's value concentrates into taste, judgement and brand guardianship. Teams get smaller, output gets bigger, and the winners direct rather than produce."},{"slug":"operations-managers","soc":"11-1021.00","cluster":"knowledge","label":"General & Operations Managers","onetTitle":"General and Operations Managers","basis":null,"counts":{"u":3,"a":10,"x":1,"n":4},"tasks":[{"id":"20699","text":"Review financial statements, sales or activity reports, or other performance data to measure productivity or goal achievement or to identify areas needing cost reduction or program improvement.","b":"a","r":"AI drafts the performance review pack and flags anomalies; deciding what to do is the job.","bl":false},{"id":"933","text":"Direct and coordinate activities of businesses or departments concerned with the production, pricing, sales, or distribution of products.","b":"u","r":"Directing the work of departments is coordination, authority and presence.","bl":false},{"id":"20700","text":"Direct administrative activities directly related to making products or providing services.","b":"a","r":"AI tracks service delivery metrics continuously; directing the operation stays human.","bl":false},{"id":"20701","text":"Prepare staff work schedules and assign specific duties.","b":"x","r":"Staff scheduling against demand and rules is a constraint problem software solves well.","bl":false},{"id":"20703","text":"Direct or coordinate financial or budget activities to fund operations, maximize investments, or increase efficiency.","b":"a","r":"AI models budget scenarios; the funding trade offs are leadership decisions.","bl":false},{"id":"20706","text":"Plan or direct activities, such as sales promotions, that require coordination with other department managers.","b":"a","r":"AI drafts the promotion plan and coordinates calendars; aligning department heads is human work.","bl":false},{"id":"20705","text":"Perform personnel functions, such as selection, training, or evaluation.","b":"a","r":"AI handles selection screening and evaluation data; hiring and developing people keeps the manager.","bl":true},{"id":"20704","text":"Establish or implement departmental policies, goals, objectives, or procedures in conjunction with board members, organization officials, or staff members.","b":"a","r":"AI drafts policy options from best practice; setting direction with the board is human.","bl":false},{"id":"20702","text":"Monitor suppliers to ensure that they efficiently and effectively provide needed goods or services within budgetary limits.","b":"a","r":"AI monitors supplier performance against contracts; the relationship and the escalation stay human.","bl":false},{"id":"20708","text":"Manage the movement of goods into and out of production facilities to ensure efficiency, effectiveness, or sustainability of operations.","b":"a","r":"AI optimises the flows and flags exceptions; directing the operation keeps the person.","bl":false},{"id":"20707","text":"Set prices or credit terms for goods or services, based on forecasts of customer demand.","b":"a","r":"AI recommends prices from demand forecasts; the pricing decision carries risk a person must own.","bl":true},{"id":"944","text":"Perform sales floor work, such as greeting or assisting customers, stocking shelves, or taking inventory.","b":"u","r":"The floor is physical. Greeting customers and shifting stock needs a body.","bl":false},{"id":"945","text":"Develop or implement product-marketing strategies, including advertising campaigns or sales promotions.","b":"a","r":"AI drafts campaign concepts and targeting; the marketing call stays with the manager.","bl":false},{"id":"947","text":"Direct non-merchandising departments of businesses, such as advertising or purchasing.","b":"u","r":"Directing support functions is coordination across strong willed departments. Human work.","bl":false}],"new":[{"t":"Run the exception queue the operations AI escalates","r":"Management by exception becomes literal. The queue is the morning meeting."},{"t":"Validate AI-generated performance narratives before they go to the board","r":"One wrong join becomes a wrong strategy."},{"t":"Set the guardrails for automated scheduling and pricing","r":"What the systems may never do is a leadership decision."},{"t":"Coach department heads to run with AI dashboards","r":"Adoption fails at the middle. The ops lead is the coach."}],"moves":{"u":"Direction, presence and the floor stay human. Everything measurable is being rebuilt around you.","a":"Run the operation on AI-drafted packs and live dashboards. Decide faster, chase data less.","x":"Automate scheduling and routine reporting first. The payback is immediate.","n":"Own the guardrails. When the system prices or rosters badly at 2am, it is your name on it."},"take":"The operations manager becomes an exception handler and guardrail setter. Routine coordination automates, dashboards replace status meetings, and the human hours shift to suppliers, people and the calls that carry risk."},{"slug":"paralegals","soc":"23-2011.00","cluster":"knowledge","label":"Paralegals & Legal Assistants","onetTitle":"Paralegals and Legal Assistants","basis":null,"counts":{"u":0,"a":7,"x":5,"n":4},"tasks":[{"id":"18491","text":"Prepare affidavits or other documents, such as legal correspondence, and organize and maintain documents in paper or electronic filing system.","b":"a","r":"AI drafts the documents and files them; the paralegal checks them against the matter.","bl":true},{"id":"23994","text":"Prepare, edit, or review legal documents, including legislation, briefs, pleadings, appeals, wills, contracts, and real estate closing statements.","b":"a","r":"AI drafts briefs and pleadings from the record; review before filing is the job now.","bl":false},{"id":"21062","text":"Investigate facts and law of cases and search pertinent sources, such as public records and internet sources, to determine causes of action and to prepare cases.","b":"a","r":"AI searches facts and law exhaustively; judging what actually helps the case stays human.","bl":false},{"id":"18492","text":"Prepare for trial by performing tasks such as organizing exhibits.","b":"a","r":"AI assembles and indexes exhibits; organising them for trial strategy stays human.","bl":false},{"id":"18493","text":"Meet with clients and other professionals to discuss details of cases.","b":"a","r":"AI prepares the briefing notes; meeting clients and reading what they leave unsaid stays human.","bl":false},{"id":"1636","text":"Gather and analyze research data, such as statutes, decisions, and legal articles, codes, and documents.","b":"x","r":"Gathering statutes, decisions and articles is research the machine does in seconds.","bl":false},{"id":"18494","text":"File pleadings with court clerks.","b":"x","r":"Filing with court clerks is electronic submission. A workflow, not a skill.","bl":false},{"id":"1639","text":"Direct and coordinate law office activity, including delivery of subpoenas.","b":"x","r":"Coordinating deliveries and office logistics routes automatically.","bl":false},{"id":"1638","text":"Call upon witnesses to testify at hearings.","b":"a","r":"AI schedules and briefs witnesses; getting a nervous witness to appear stays human.","bl":false},{"id":"18496","text":"Arbitrate disputes between parties and assist in the real estate closing process, such as by reviewing title searches.","b":"a","r":"AI reviews title searches and flags issues; assisting at closing needs a person across the table.","bl":true},{"id":"1642","text":"Appraise and inventory real and personal property for estate planning.","b":"x","r":"Inventorying and appraising against records is data compilation.","bl":false},{"id":"1641","text":"Keep and monitor legal volumes to ensure that the law library is up-to-date.","b":"x","r":"Keeping the law library current is a subscription feed, not a task.","bl":false}],"new":[{"t":"Verify AI-drafted filings citation by citation","r":"A hallucinated case in a pleading is sanctions for the firm. The checker is the firewall."},{"t":"Run the e-discovery AI and defend its output","r":"Machine review is standard now; someone must stand behind the method."},{"t":"Maintain the matter knowledge base the AI drafts from","r":"Better inputs, better drafts. Curation is the new research."},{"t":"Flag what the AI review missed for attorney attention","r":"Knowing where the tool is weak is the new expertise."}],"moves":{"u":"Client contact and closing support stay human. Trust in stressful moments is the durable value.","a":"Become the firm's chief verifier: AI drafts, the paralegal checks every line before filing.","x":"Automate research gathering, filing and records. This layer is already gone in leading firms.","n":"Own citation verification and AI output quality. It is the role that keeps the firm out of trouble."},"take":"The traditional paralegal bundle (research, drafting, filing) is ground zero for legal AI. The role survives as verification and client handling, but the headcount maths of the old model does not."},{"slug":"project-managers","soc":"13-1082.00","cluster":"knowledge","label":"Project Managers","onetTitle":"Project Management Specialists","basis":null,"counts":{"u":0,"a":9,"x":5,"n":4},"tasks":[{"id":"21462","text":"Assign duties or responsibilities to project personnel.","b":"a","r":"AI proposes assignments from skills and availability data; the PM balances the people politics.","bl":true},{"id":"21463","text":"Communicate with key stakeholders to determine project requirements and objectives.","b":"a","r":"AI drafts the requirements summary from every call; drawing out what stakeholders actually mean stays human.","bl":false},{"id":"21464","text":"Confer with project personnel to identify and resolve problems.","b":"a","r":"AI surfaces the blocker from status data early; unblocking it usually needs a conversation.","bl":false},{"id":"21465","text":"Create project status presentations for delivery to customers or project personnel.","b":"x","r":"Status decks compile themselves from the project system. Review and send.","bl":false},{"id":"21466","text":"Develop or update project plans including information such as objectives, technologies, schedules, funding, and staffing.","b":"a","r":"AI maintains the living plan and replans instantly; committing the plan is the PM's call.","bl":false},{"id":"21467","text":"Identify project needs such as resources, staff, or finances by reviewing project objectives and schedules.","b":"a","r":"AI drafts resourcing options from the plan; negotiating for people is internal politics.","bl":false},{"id":"21468","text":"Identify, review, or select vendors or consultants to meet project needs.","b":"a","r":"AI shortlists vendors against criteria; selecting who the work depends on stays human.","bl":false},{"id":"21469","text":"Monitor costs incurred by project staff to identify budget issues.","b":"x","r":"Cost tracking against budget is continuous computation with alerts.","bl":false},{"id":"21470","text":"Monitor project milestones and deliverables.","b":"x","r":"Milestone monitoring is a dashboard, not a diary entry.","bl":false},{"id":"21471","text":"Monitor the performance of project team members to provide performance feedback.","b":"a","r":"AI assembles delivery data per person; performance feedback is a human conversation.","bl":false},{"id":"21472","text":"Negotiate with project stakeholders or suppliers to obtain resources or materials.","b":"a","r":"AI models negotiation positions; the negotiating itself stays across the table.","bl":false},{"id":"21473","text":"Plan, schedule, or coordinate project activities to meet deadlines.","b":"a","r":"AI optimises the schedule against dependencies; coordinating the humans inside it stays human.","bl":true},{"id":"21474","text":"Prepare and submit budget estimates, progress reports, or cost tracking reports.","b":"x","r":"Budget estimates, progress and cost reports generate from live data.","bl":false},{"id":"21475","text":"Produce and distribute project documents.","b":"x","r":"Document production and distribution is automated the moment the plan lives in a system.","bl":false}],"new":[{"t":"Interrogate the AI risk forecast before trusting it","r":"The model sees patterns, not politics. Knowing the difference is the job."},{"t":"Run the automated status pipeline and its exceptions","r":"When status writes itself, the PM's week is unblocking, not collecting."},{"t":"Coach the team to keep the project system truthful","r":"AI reporting is only as good as the data the team feeds it."},{"t":"Decide what the automation may commit to","r":"Which changes the AI may make alone is a governance call."}],"moves":{"u":"Stakeholder wrangling, negotiation and feedback stay human. That was always the hard part.","a":"Live in the exceptions: the AI flags risk, the PM fixes it. Chasing status is over.","x":"Automate reporting, tracking and documentation completely. Reclaim a day a week.","n":"Own the governance: what the tools may decide alone, and what always comes to a person."},"take":"Half the traditional PM week (status collection, reporting, documentation) evaporates. The role becomes exception handling, stakeholder management and judgement about risk, which is what good PMs always wanted it to be."},{"slug":"registered-nurses","soc":"29-1141.00","cluster":"knowledge","label":"Registered Nurses","onetTitle":"Registered Nurses","basis":null,"counts":{"u":5,"a":10,"x":0,"n":4},"tasks":[{"id":"1841","text":"Record patients' medical information and vital signs.","b":"a","r":"AI captures vitals from devices and drafts the entry; the nurse verifies and owns the record.","bl":false},{"id":"20413","text":"Administer medications to patients and monitor patients for reactions or side effects.","b":"u","r":"Administering medication safely is hands, checks and accountability at the bedside.","bl":false},{"id":"1839","text":"Maintain accurate, detailed reports and records.","b":"a","r":"AI drafts documentation from the shift's data; the nurse confirms it against reality.","bl":false},{"id":"1840","text":"Monitor, record, and report symptoms or changes in patients' conditions.","b":"a","r":"AI monitors trends and flags deterioration early; the nurse judges what the monitor cannot see.","bl":true},{"id":"1855","text":"Provide health care, first aid, immunizations, or assistance in convalescence or rehabilitation in locations such as schools, hospitals, or industry.","b":"u","r":"Hands on care, first aid and immunisation need a trained human body in the room.","bl":false},{"id":"1843","text":"Consult and coordinate with healthcare team members to assess, plan, implement, or evaluate patient care plans.","b":"a","r":"AI keeps the care plan current and coordinates the handover data; the team conversation stays human.","bl":false},{"id":"1846","text":"Direct or supervise less-skilled nursing or healthcare personnel or supervise a particular unit.","b":"u","r":"Directing and supervising junior staff is clinical leadership on the ward.","bl":false},{"id":"1845","text":"Monitor all aspects of patient care, including diet and physical activity.","b":"a","r":"AI tracks diet and activity data continuously; judging the whole patient stays human.","bl":false},{"id":"1850","text":"Instruct individuals, families, or other groups on topics such as health education, disease prevention, or childbirth and develop health improvement programs.","b":"a","r":"AI personalises education materials; teaching a worried family is human communication.","bl":false},{"id":"1842","text":"Modify patient treatment plans as indicated by patients' responses and conditions.","b":"a","r":"AI proposes plan adjustments from response data; modifying treatment is clinical judgement.","bl":false},{"id":"1857","text":"Conduct specified laboratory tests.","b":"a","r":"AI runs the analysers and flags results; the nurse validates what matters clinically.","bl":true},{"id":"1848","text":"Observe nurses and visit patients to ensure proper nursing care.","b":"u","r":"Observing practice and visiting patients is quality and presence. No shortcut.","bl":false},{"id":"1849","text":"Assess the needs of individuals, families, or communities, including assessment of individuals' home or work environments, to identify potential health or safety problems.","b":"a","r":"AI maps risk factors from records; assessing a home's safety needs eyes on it.","bl":false},{"id":"1865","text":"Work with individuals, groups, or families to plan or implement programs designed to improve the overall health of communities.","b":"a","r":"AI drafts programme designs from population data; implementing them with communities stays human.","bl":false},{"id":"1847","text":"Prepare patients for and assist with examinations or treatments.","b":"u","r":"Preparing and reassuring a patient before a procedure is care itself.","bl":false}],"new":[{"t":"Act on AI early-warning scores before the crisis","r":"The alert only helps if a skilled human responds. Response protocol is new work."},{"t":"Verify AI-drafted chart entries against the actual patient","r":"Documentation errors compound into treatment errors. Check the machine."},{"t":"Translate AI risk flags for anxious families","r":"The model says probability; the nurse says what it means for mum."},{"t":"Guard against alert fatigue as monitoring multiplies","r":"More flags, more noise. Someone tunes the system and watches for drift."}],"moves":{"u":"The bedside is the moat. Physical care, supervision and reassurance are the durable core of nursing.","a":"Let AI watch the data and draft the notes. Reinvest the hours in patients, not keyboards.","x":"Very little here fully automates. That is the point: nursing is presence work.","n":"Own the AI monitoring loop: respond, verify, translate. It is clinical work now."},"take":"Anthropic chose the nurse for a reason: the bundle splits into documentation (which melts away) and presence (which does not). AI returns hours to the bedside rather than removing the nurse from it. If only every role read like this."},{"slug":"sales-managers","soc":"11-2022.00","cluster":"knowledge","label":"Sales Managers","onetTitle":"Sales Managers","basis":null,"counts":{"u":2,"a":11,"x":2,"n":4},"tasks":[{"id":"14","text":"Oversee regional and local sales managers and their staffs.","b":"u","r":"Leading salespeople is coaching, motivation and hard conversations. Human throughout.","bl":false},{"id":"1","text":"Resolve customer complaints regarding sales and service.","b":"a","r":"AI drafts the response and finds precedent; calming an unhappy customer stays human.","bl":true},{"id":"2","text":"Monitor customer preferences to determine focus of sales efforts.","b":"a","r":"AI tracks preference signals across the CRM; deciding where to point the team stays human.","bl":false},{"id":"13","text":"Confer with potential customers regarding equipment needs, and advise customers on types of equipment to purchase.","b":"a","r":"AI prepares the needs analysis and the quote; advising the customer face to face is the sale.","bl":false},{"id":"5","text":"Review operational records and reports to project sales and determine profitability.","b":"a","r":"AI projects sales and margin from the records; the call on what to chase stays human.","bl":false},{"id":"11","text":"Plan and direct staffing, training, and performance evaluations to develop and control sales and service programs.","b":"a","r":"AI drafts programmes and evaluation data; developing salespeople is coaching, person to person.","bl":false},{"id":"3","text":"Direct and coordinate activities involving sales of manufactured products, services, commodities, real estate, or other subjects of sale.","b":"u","r":"Directing the sales effort is leadership under target pressure. No delegation.","bl":false},{"id":"4","text":"Determine price schedules and discount rates.","b":"a","r":"AI optimises price and discount against data; the pricing call carries margin risk a person owns.","bl":true},{"id":"9","text":"Prepare budgets and approve budget expenditures.","b":"a","r":"AI drafts the budget and tracks spend; approving expenditure stays human.","bl":false},{"id":"7","text":"Confer or consult with department heads to plan advertising services and to secure information on equipment and customer specifications.","b":"a","r":"AI prepares the briefs; aligning department heads is internal diplomacy.","bl":false},{"id":"12","text":"Visit franchised dealers to stimulate interest in establishment or expansion of leasing programs.","b":"a","r":"AI arms the visit with data and talking points; stimulating dealers is relationship work.","bl":false},{"id":"10","text":"Represent company at trade association meetings to promote products.","b":"a","r":"AI drafts the position and briefing; representing the company at the table stays human.","bl":false},{"id":"8","text":"Advise dealers and distributors on policies and operating procedures to ensure functional effectiveness of business.","b":"a","r":"AI drafts the policy guidance; advising distributors is partnership, not paperwork.","bl":false},{"id":"6","text":"Direct, coordinate, and review sales and service accounting and record-keeping, as well as receiving and shipping.","b":"x","r":"Sales accounting, receiving and shipping records are system administration.","bl":false},{"id":"15","text":"Direct clerical staff to keep records of export correspondence, bid requests, and credit collections, and to maintain current information on tariffs, licenses, and restrictions.","b":"x","r":"Directing clerical record keeping is supervising what should now be software.","bl":false}],"new":[{"t":"Audit AI-generated forecasts before committing the number","r":"The board holds you to the number. Know how the model built it."},{"t":"Coach the team to sell alongside AI agents","r":"When the buyer has an AI assistant too, the playbook changes."},{"t":"Review AI-drafted customer communications at scale","r":"One tone-deaf automated email can cost a key account."},{"t":"Set the rules for automated outreach: volume, tone, limits","r":"Reputation risk is now a configuration setting. Someone owns it."}],"moves":{"u":"Leadership and customer relationships stay human. Selling was always trust; the admin around it just died.","a":"Let AI handle the analysis, briefs and forecasts. Spend the recovered hours in the field with reps and customers.","x":"Automate sales administration completely. CRM hygiene should be a byproduct, not a chore.","n":"Own the outreach rules. Automated selling done badly torches the brand at scale."},"take":"Sales management sheds its reporting burden and doubles down on its human core: coaching reps and winning trust. The risk sits at the edges: automated outreach and AI-drafted promises need a human governor."},{"slug":"secondary-teachers","soc":"25-2031.00","cluster":"knowledge","label":"Secondary School Teachers","onetTitle":"Secondary School Teachers, Except Special and Career/Technical Education","basis":null,"counts":{"u":5,"a":13,"x":2,"n":4},"tasks":[{"id":"6650","text":"Prepare students for later grades by encouraging them to explore learning opportunities and to persevere with challenging tasks.","b":"u","r":"Encouraging teenagers through hard things is relationship, timing and belief. The human is the intervention.","bl":false},{"id":"6640","text":"Instruct through lectures, discussions, and demonstrations in one or more subjects, such as English, mathematics, or social studies.","b":"a","r":"AI drafts explanations and examples for every level; the teacher performs, adapts and reads the room.","bl":false},{"id":"6639","text":"Establish and enforce rules for behavior and procedures for maintaining order among students.","b":"u","r":"Order in a room of thirty adolescents is authority and relationship. No app manages a classroom.","bl":false},{"id":"6643","text":"Prepare materials and classrooms for class activities.","b":"x","r":"Preparing materials and rooms is production and logistics. AI drafts the materials instantly.","bl":false},{"id":"6644","text":"Adapt teaching methods and instructional materials to meet students' varying needs and interests.","b":"a","r":"AI generates differentiated versions for every need; choosing what fits these students stays human.","bl":false},{"id":"6642","text":"Prepare, administer, and grade tests and assignments to evaluate students' progress.","b":"a","r":"AI drafts and marks standard assessments; judging the edge cases and the effort stays human.","bl":true},{"id":"6641","text":"Establish clear objectives for all lessons, units, and projects, and communicate those objectives to students.","b":"a","r":"AI drafts objectives from the curriculum; the teacher decides what these students need next.","bl":false},{"id":"6647","text":"Observe and evaluate students' performance, behavior, social development, and physical health.","b":"a","r":"AI tracks performance data and flags patterns; noticing the quiet kid who is struggling stays human.","bl":false},{"id":"6649","text":"Plan and conduct activities for a balanced program of instruction, demonstration, and work time that provides students with opportunities to observe, question, and investigate.","b":"a","r":"AI sequences the activities and resources; conducting the lesson is live craft.","bl":false},{"id":"6651","text":"Guide and counsel students with adjustments, academic problems, or special academic interests.","b":"u","r":"Counselling a teenager through problems is trust. They talk to the person, not the tool.","bl":false},{"id":"6654","text":"Use computers, audio-visual aids, and other equipment and materials to supplement presentations.","b":"a","r":"AI assembles the multimedia resources; using them well in a live lesson stays human.","bl":false},{"id":"6657","text":"Prepare objectives and outlines for courses of study, following curriculum guidelines or requirements of states and schools.","b":"a","r":"AI drafts the outlines against curriculum requirements; the teacher owns the year's arc.","bl":false},{"id":"6646","text":"Assign and grade class work and homework.","b":"a","r":"AI marks objective work instantly and drafts feedback; the teacher reviews what matters.","bl":true},{"id":"6645","text":"Maintain accurate and complete student records as required by laws, district policies, and administrative regulations.","b":"x","r":"Statutory record keeping is structured data entry. Automate every field possible.","bl":false},{"id":"6648","text":"Enforce all administration policies and rules governing students.","b":"u","r":"Enforcing rules fairly across thirty individuals is judgement and relationship.","bl":false},{"id":"6656","text":"Confer with parents or guardians, other teachers, counselors, and administrators to resolve students' behavioral and academic problems.","b":"u","r":"Resolving problems with parents and colleagues is diplomacy. Human throughout.","bl":false},{"id":"6661","text":"Confer with other staff members to plan and schedule lessons promoting learning, following approved curricula.","b":"a","r":"AI drafts the plans and schedules; planning with colleagues is professional conversation.","bl":false},{"id":"6659","text":"Prepare and implement remedial programs for students requiring extra help.","b":"a","r":"AI drafts remedial materials from the gap analysis; deciding who needs what stays human.","bl":false},{"id":"6670","text":"Provide students with disabilities with assistive devices, supportive technology, and assistance accessing facilities such as restrooms.","b":"a","r":"AI matches assistive tech to needs; the daily support of a disabled student is human care.","bl":false},{"id":"6658","text":"Meet with other professionals to discuss individual students' needs and progress.","b":"a","r":"AI prepares the case summaries; the meeting about a child is professional judgement shared.","bl":false}],"new":[{"t":"Detect AI-written homework without accusing unfairly","r":"The plagiarism arms race needs judgement, not just detectors."},{"t":"Teach students to use AI without outsourcing their thinking","r":"AI literacy becomes part of every subject. Someone has to design it."},{"t":"Verify AI-drafted feedback before a child reads it","r":"A careless generated comment can flatten a fragile student."},{"t":"Run AI tutoring for practice while keeping humans for teaching","r":"Drill and explanation split apart. Designing the blend is new craft."}],"moves":{"u":"Classroom presence, counselling and relationships are the durable heart of teaching. Protect the time for them.","a":"Let AI draft, differentiate and mark. Reinvest the hours in the students in front of you.","x":"Automate records and material production. The Sunday marking pile should become history.","n":"Own AI literacy and verification. The teacher now teaches with, about and sometimes against AI."},"take":"Administration and material production (the burnout engine) collapse, while everything that makes teaching work (presence, relationship, judgement about young people) stays human. Done right, AI gives teachers back their evenings, not their pink slips."},{"slug":"software-developers","soc":"15-1252.00","cluster":"knowledge","label":"Software Developers","onetTitle":"Software Developers","basis":null,"counts":{"u":1,"a":9,"x":4,"n":4},"tasks":[{"id":"21662","text":"Analyze user needs and software requirements to determine feasibility of design within time and cost constraints.","b":"a","r":"AI drafts the feasibility analysis; judging what is worth building needs product context.","bl":false},{"id":"21669","text":"Develop or direct software system testing or validation procedures, programming, or documentation.","b":"a","r":"AI generates the test suites and documentation; deciding what good enough means stays human.","bl":false},{"id":"21664","text":"Confer with systems analysts, engineers, programmers and others to design systems and to obtain information on project limitations and capabilities, performance requirements and interfaces.","b":"a","r":"AI answers the technical questions instantly; designing systems with other humans is negotiation.","bl":false},{"id":"21670","text":"Modify existing software to correct errors, adapt it to new hardware, or upgrade interfaces and improve performance.","b":"a","r":"AI drafts the fix and the refactor; reviewing it before it ships is the job now.","bl":true},{"id":"21673","text":"Prepare reports or correspondence concerning project specifications, activities, or status.","b":"x","r":"Status reports and correspondence compile from the tracker. Write code, not updates.","bl":false},{"id":"21661","text":"Analyze information to determine, recommend, and plan installation of a new system or modification of an existing system.","b":"a","r":"AI proposes the change plan from the codebase; the install decision carries risk a person owns.","bl":false},{"id":"21676","text":"Store, retrieve, and manipulate data for analysis of system capabilities and requirements.","b":"x","r":"Data plumbing for analysis is generated code and scheduled jobs.","bl":false},{"id":"21667","text":"Design, develop and modify software systems, using scientific analysis and mathematical models to predict and measure outcomes and consequences of design.","b":"a","r":"AI designs and writes the first implementation; consequences of the design stay with the engineer.","bl":true},{"id":"21668","text":"Determine system performance standards.","b":"a","r":"AI benchmarks against standards automatically; setting the bar for this product stays human.","bl":false},{"id":"21665","text":"Consult with customers or other departments on project status, proposals, or technical issues, such as software system design or maintenance.","b":"a","r":"AI drafts the status and the proposals; consulting with customers is relationship work.","bl":false},{"id":"21663","text":"Confer with data processing or project managers to obtain information on limitations or capabilities for data processing projects.","b":"a","r":"AI retrieves the constraint details; aligning with other teams is human coordination.","bl":false},{"id":"21671","text":"Monitor functioning of equipment to ensure system operates in conformance with specifications.","b":"x","r":"Monitoring against specifications is what observability tooling already does.","bl":false},{"id":"21666","text":"Coordinate installation of software system.","b":"x","r":"Coordinating installs is scripted deployment and runbooks.","bl":false},{"id":"21678","text":"Supervise the work of programmers, technologists and technicians and other engineering and scientific personnel.","b":"u","r":"Leading other engineers is mentorship, review and judgement about people.","bl":false}],"new":[{"t":"Review AI-generated code for security and subtle failure","r":"The bug rate shifts from typos to plausible wrongness. Review skill becomes the bottleneck."},{"t":"Write the specifications the AI builds from","r":"Precise intent becomes more valuable than fast typing."},{"t":"Own the agentic pipeline: prompts, tools, guardrails, tests","r":"The developer becomes the foreman of a tireless junior team."},{"t":"Verify AI claims about the codebase before acting on them","r":"Models state falsehoods fluently. Trust, but grep."}],"moves":{"u":"System design with humans and leading engineers stay. The social layer of software is durable.","a":"Shift from writer to reviewer and architect. Output per developer jumps; judgement per line matters more.","x":"Let status, plumbing and monitoring run themselves. They were never the craft.","n":"Master the new core skill: specifying precisely and verifying ruthlessly."},"take":"The most AI-exposed craft role in the index, and the most augmented rather than replaced: code generation is nearly free, so the value concentrates in specification, review and design judgement. Senior engineers get leverage; the junior task ladder needs rebuilding."},{"slug":"technical-writers","soc":"27-3042.00","cluster":"knowledge","label":"Technical Writers","onetTitle":"Technical Writers","basis":null,"counts":{"u":1,"a":11,"x":3,"n":4},"tasks":[{"id":"3966","text":"Organize material and complete writing assignment according to set standards regarding order, clarity, conciseness, style, and terminology.","b":"a","r":"AI drafts to the style standard from source material; the writer edits for truth and clarity.","bl":false},{"id":"3967","text":"Maintain records and files of work and revisions.","b":"x","r":"Revision records keep themselves in any modern system.","bl":false},{"id":"3968","text":"Edit, standardize, or make changes to material prepared by other writers or establishment personnel.","b":"a","r":"AI proposes the edits; standardising voice across writers is human editorial judgement.","bl":true},{"id":"3971","text":"Select photographs, drawings, sketches, diagrams, and charts to illustrate material.","b":"a","r":"AI suggests illustrations and drafts diagrams; choosing what clarifies rather than decorates stays human.","bl":false},{"id":"3973","text":"Interview production and engineering personnel and read journals and other material to become familiar with product technologies and production methods.","b":"u","r":"Interviewing engineers is how the unwritten knowledge surfaces. The conversation is the research.","bl":false},{"id":"20243","text":"Develop or maintain online help documentation.","b":"a","r":"AI drafts and updates help content from the codebase; the writer verifies every claim.","bl":false},{"id":"3976","text":"Assist in laying out material for publication.","b":"a","r":"AI handles layout from templates; publication judgement stays human.","bl":false},{"id":"3972","text":"Study drawings, specifications, mockups, and product samples to integrate and delineate technology, operating procedure, and production sequence and detail.","b":"a","r":"AI reads the specs and drafts the procedures; integrating them into a coherent whole is craft.","bl":true},{"id":"3975","text":"Arrange for typing, duplication, and distribution of material.","b":"x","r":"Typing, duplication and distribution are a publishing pipeline, not a task.","bl":false},{"id":"3974","text":"Observe production, developmental, and experimental activities to determine operating procedure and detail.","b":"a","r":"AI summarises test output; observing the machine actually run and catching what specs miss is human.","bl":false},{"id":"3978","text":"Review manufacturer's and trade catalogs, drawings and other data relative to operation, maintenance, and service of equipment.","b":"x","r":"Reviewing catalogues and data sheets for facts is machine reading at scale.","bl":false},{"id":"3977","text":"Analyze developments in specific field to determine need for revisions in previously published materials and development of new material.","b":"a","r":"AI flags when the product changed; deciding what the docs must say about it stays human.","bl":false},{"id":"3979","text":"Draw sketches to illustrate specified materials or assembly sequence.","b":"a","r":"AI drafts the diagrams from description; judging whether a reader will understand it stays human.","bl":false},{"id":"3970","text":"Review published materials and recommend revisions or changes in scope, format, content, and methods of reproduction and binding.","b":"a","r":"AI drafts the revision list from feedback; scope and format calls stay with the writer.","bl":false},{"id":"3969","text":"Confer with customer representatives, vendors, plant executives, or publisher to establish technical specifications and to determine subject material to be developed for publication.","b":"a","r":"AI prepares the briefing; pinning down engineers on what the product really does is persistence, human to human.","bl":false}],"new":[{"t":"Verify AI-drafted documentation against the actual product","r":"Docs that confidently describe behaviour the product does not have are worse than no docs."},{"t":"Write the content the AI support assistant answers from","r":"The knowledge base is the product's voice now. Someone authors it."},{"t":"Test instructions with AI readers before human ones","r":"Instant feedback on clarity changes the editing cycle."},{"t":"Own the docs pipeline: source, generate, verify, publish","r":"The writer becomes the editor of a documentation machine."}],"moves":{"u":"Interviewing engineers and extracting unwritten knowledge stays human. That was always the scarce skill.","a":"Shift from writing to editing and verifying. The blank page is gone; the red pen rules.","x":"Automate publishing, records and fact extraction. Pipelines, not people.","n":"Own AI doc verification. Accuracy is the entire product, and someone must guarantee it."},"take":"Drafting was the bulk of the hours and it compresses hard. What survives is what was always rare: extracting knowledge from engineers, judging clarity for real readers, and guaranteeing that every word is true."},{"slug":"training-development-managers","soc":"11-3131.00","cluster":"people","label":"Training & Development Managers","onetTitle":"Training and Development Managers","basis":null,"counts":{"u":0,"a":9,"x":3,"n":4},"tasks":[{"id":"1015","text":"Analyze training needs to develop new training programs or modify and improve existing programs.","b":"a","r":"AI mines performance data for skill gaps and drafts programme designs; the manager picks what the business needs.","bl":false},{"id":"1009","text":"Evaluate instructor performance and the effectiveness of training programs, providing recommendations for improvement.","b":"a","r":"AI correlates training with outcomes; judging instructor quality still takes a human observer.","bl":true},{"id":"1014","text":"Plan, develop, and provide training and staff development programs, using knowledge of the effectiveness of methods such as classroom training, demonstrations, on-the-job training, meetings, conferences, and workshops.","b":"a","r":"AI personalises content and pathways at scale; the manager sets the curriculum's intent.","bl":false},{"id":"1012","text":"Confer with management and conduct surveys to identify training needs based on projected production processes, changes, and other factors.","b":"a","r":"AI runs the surveys and drafts the needs analysis; conferring with management stays a conversation.","bl":false},{"id":"1008","text":"Conduct orientation sessions and arrange on-the-job training for new hires.","b":"a","r":"AI schedules and tailors onboarding; the first week experience still needs human hosts.","bl":false},{"id":"1017","text":"Train instructors and supervisors in techniques and skills for training and dealing with employees.","b":"a","r":"AI builds the coaching materials; developing instructors is demonstration and feedback, person to person.","bl":false},{"id":"1013","text":"Develop and organize training manuals, multimedia visual aids, and other educational materials.","b":"x","r":"Producing manuals, slides and visual aids is content production. AI drafts, the manager approves.","bl":false},{"id":"1019","text":"Prepare training budget for department or organization.","b":"a","r":"AI drafts the budget and tracks spend; the trade offs between programmes stay human.","bl":false},{"id":"1010","text":"Develop testing and evaluation procedures.","b":"a","r":"AI generates assessments and scoring; deciding what good looks like stays human.","bl":false},{"id":"1011","text":"Conduct or arrange for ongoing technical training and personal development classes for staff members.","b":"a","r":"AI matches content to needs and schedules delivery; spotting who is struggling stays human.","bl":true},{"id":"1016","text":"Review and evaluate training and apprenticeship programs for compliance with government standards.","b":"x","r":"Compliance review of programmes against standards is rule checking. Automate, then sample.","bl":false},{"id":"1018","text":"Coordinate established courses with technical and professional courses provided by community schools, and designate training procedures.","b":"x","r":"Coordinating course logistics with external providers is scheduling and admin.","bl":false}],"new":[{"t":"Quality-check AI-generated training content before it ships","r":"Confident, fluent and wrong is the default failure mode. Review is the job."},{"t":"Design the AI tutor guardrails for the organisation","r":"What the tutor may teach, and where it must stop, is a policy decision."},{"t":"Measure skill change, not course completion","r":"AI finally makes outcome measurement cheap. Use it."},{"t":"Curate the knowledge the AI teaches from","r":"The corpus is the curriculum now. Someone owns it."}],"moves":{"u":"Programme judgement and instructor development stay human. Protect them.","a":"Let AI personalise, schedule and draft. The manager moves from running courses to designing learning.","x":"Automate content production, logistics and compliance checks. Reinvest the hours in outcomes.","n":"The new craft is supervising AI tutors: quality, guardrails, evidence of skill change."},"take":"Content production (the historical bottleneck in L&D) just became nearly free. The role moves up a level: less building courses, more proving that skills actually changed."},{"slug":"training-development-specialists","soc":"13-1151.00","cluster":"people","label":"Training & Development Specialists","onetTitle":"Training and Development Specialists","basis":null,"counts":{"u":1,"a":12,"x":5,"n":4},"tasks":[{"id":"94","text":"Present information with a variety of instructional techniques or formats, such as role playing, simulations, team exercises, group discussions, videos, or lectures.","b":"u","r":"Live facilitation is performance and adaptation in the room. AI assists; it does not hold the room.","bl":false},{"id":"20475","text":"Obtain, organize, or develop training procedure manuals, guides, or course materials, such as handouts or visual materials.","b":"x","r":"Assembling manuals, guides and handouts is content production. AI drafts from source material.","bl":false},{"id":"19559","text":"Evaluate modes of training delivery, such as in-person or virtual, to optimize training effectiveness, training costs, or environmental impacts.","b":"a","r":"AI compares delivery modes on cost and outcome data; the specialist judges what fits the learners.","bl":false},{"id":"97","text":"Offer specific training programs to help workers maintain or improve job skills.","b":"a","r":"AI identifies skill gaps and matches content; delivering the programme keeps the human.","bl":true},{"id":"103","text":"Assess training needs through surveys, interviews with employees, focus groups, or consultation with managers, instructors, or customer representatives.","b":"a","r":"AI runs surveys and synthesis at scale; the interviews and focus groups stay human conversations.","bl":false},{"id":"98","text":"Monitor, evaluate, or record training activities or program effectiveness.","b":"a","r":"AI tracks activity and outcome metrics continuously; judging effectiveness needs context.","bl":false},{"id":"20474","text":"Design, plan, organize, or direct orientation and training programs for employees or customers.","b":"a","r":"AI drafts the programme structure and materials; the design intent stays with the specialist.","bl":false},{"id":"102","text":"Develop alternative training methods if expected improvements are not seen.","b":"a","r":"AI proposes alternative methods from evidence; choosing the pivot is professional judgement.","bl":false},{"id":"101","text":"Evaluate training materials prepared by instructors, such as outlines, text, or handouts.","b":"a","r":"AI checks materials against standards; evaluating whether they teach well keeps a human.","bl":true},{"id":"20476","text":"Monitor training costs and prepare budget reports to justify expenditures.","b":"x","r":"Cost monitoring and budget reports are scheduled computation.","bl":false},{"id":"106","text":"Devise programs to develop executive potential among employees in lower-level positions.","b":"a","r":"AI maps development paths from skills data; spotting executive potential is human judgement.","bl":false},{"id":"93","text":"Keep up with developments in area of expertise by reading current journals, books, or magazine articles.","b":"a","r":"AI curates and summarises new research daily; staying sharp still takes the person.","bl":false},{"id":"99","text":"Attend meetings or seminars to obtain information for use in training programs or to inform management of training program status.","b":"x","r":"Status reporting on programmes is compiled, not crafted. Automate it.","bl":false},{"id":"100","text":"Coordinate recruitment and placement of training program participants.","b":"x","r":"Coordinating enrolment and placement is workflow administration.","bl":false},{"id":"105","text":"Select and assign instructors to conduct training.","b":"a","r":"AI matches instructors to sessions by skill and availability; the assignment call stays human.","bl":false},{"id":"108","text":"Negotiate contracts with clients for desired training outcomes, fees, or expenses.","b":"a","r":"AI drafts the proposal and cost model; negotiating with the client stays person to person.","bl":false},{"id":"20477","text":"Supervise, evaluate, or refer instructors to skill development classes.","b":"a","r":"AI flags instructors needing support from feedback data; the referral conversation is human.","bl":false},{"id":"95","text":"Schedule classes based on availability of classrooms, equipment, or instructors.","b":"x","r":"Timetabling classes against rooms and availability is a constraint solver's job.","bl":false}],"new":[{"t":"Review AI-generated course content for accuracy and tone","r":"Fluent and wrong is the default failure. Every module gets a human pass."},{"t":"Coach facilitators to work alongside AI tutors","r":"Blended delivery is a new skill. Someone has to teach it."},{"t":"Run the AI practice partner for role plays and simulations","r":"Simulations at scale become possible; designing and debriefing them is human work."},{"t":"Build the evidence trail that training changed behaviour","r":"Completion certificates are over. Skill proof is the new deliverable."}],"moves":{"u":"Facilitation is the durable core. Invest in it; everything around it is being rebuilt.","a":"Let AI do needs analysis, content drafts and scheduling. Deliver more, administer less.","x":"Automate logistics, reporting and content assembly. Nobody misses doing them.","n":"Own AI content quality. The specialist who can guarantee accuracy becomes indispensable."},"take":"The specialist who delivers stays valuable; the specialist who mostly assembles materials is exposed. Live facilitation holds, production work goes, and a new craft (supervising AI generated learning) arrives."}],"stats":{"roles":27,"tasks":420,"new":111,"agg":{"u":43,"a":283,"x":94}}};
